def _agent_platform_policy(name, action):
    return {
        "name": name,
        "arn": f"arn:aws:iam::123456789012:policy/{name}",
        "document": {
            "Statement": {
                "Effect": "Allow",
                "Action": action,
                "Resource": "*",
            }
        },
    }


