    @patch("agentcore_app.agentcore_client")
    def test_ac07_each_describe_error_names_its_own_fix(self, mock_ac):
        """AccessDenied can come from KMS, and only NotFound means deleted.

        A caller that holds bedrock-agentcore:GetMemory but not kms:Decrypt on a
        memory's customer managed key is denied GetMemory, so a resolution that
        names only the AgentCore grant, or a deleted memory, sends the reader to
        the wrong fix.
        """
        mock_ac.list_memories.return_value = {
            "memories": [
                {"id": "mem-1", "name": "Denied"},
                {"id": "mem-2", "name": "Gone"},
                {"id": "mem-3", "name": "Throttled"},
                {"id": "mem-4", "name": "Readable"},
            ]
        }
        mock_ac.get_memory.side_effect = [
            _make_client_error("AccessDeniedException", "no"),
            _make_client_error("ResourceNotFoundException", "gone"),
            _make_client_error("ThrottledException", "slow down"),
            {"memory": self._memory_detail()},
        ]

        findings = extract_csv_data(
            agentcore_app.check_agentcore_memory_configuration()
        )

        assert [f["Status"] for f in findings] == [
            "N/A",
            "N/A",
            "N/A",
            "Passed",
            "Passed",
        ]
        denied, gone, throttled = findings[:3]
        assert "'Denied' (mem-1)" in denied["Finding_Details"]
        assert "kms:Decrypt" in denied["Resolution"]
        assert "key policy" in denied["Resolution"]
        assert "kms:ViaService" in denied["Resolution"]
        assert "bedrock-agentcore:GetMemory" in denied["Resolution"]
        assert "kms:Decrypt" in denied["Finding_Details"]
        assert "deleted mid-assessment" not in denied["Resolution"]
        assert "'Gone' (mem-2)" in gone["Finding_Details"]
        assert "deleted mid-assessment" in gone["Resolution"]
        assert "kms:Decrypt" not in gone["Resolution"] + gone["Finding_Details"]
        assert "'Throttled' (mem-3)" in throttled["Finding_Details"]
        assert "bedrock-agentcore:GetMemory" in throttled["Resolution"]
        assert "deleted mid-assessment" not in throttled["Resolution"]
        assert "kms:Decrypt" not in throttled["Resolution"]

    @patch("agentcore_app.agentcore_client")
    def test_ac07_access_denied_cause_reaches_the_ag19_row(self, mock_ac):
        """AG-19 copies AC-07's details, not its resolution, so the cause is there."""
        mock_ac.list_memories.return_value = {
            "memories": [
                {"id": "mem-1", "name": "Denied"},
                {"id": "mem-2", "name": "Gone"},
            ]
        }
        mock_ac.get_memory.side_effect = [
            _make_client_error("AccessDeniedException", "no"),
            _make_client_error("ResourceNotFoundException", "gone"),
        ]

        derived = agentcore_app.build_agentic_agentcore_security_findings(
            extract_csv_data(agentcore_app.check_agentcore_memory_configuration())
        )

        assert [f["Check_ID"] for f in derived] == ["AG-19", "AG-19"]
        assert [f["Status"] for f in derived] == ["N/A", "N/A"]
        assert [f["Severity"] for f in derived] == ["Informational", "Informational"]
        assert "kms:Decrypt" in derived[0]["Finding_Details"]
        assert "'Denied' (mem-1)" in derived[0]["Finding_Details"]
        assert "kms:Decrypt" not in derived[1]["Finding_Details"]
        assert "'Gone' (mem-2)" in derived[1]["Finding_Details"]
        for finding in derived:
            assert_finding_schema(finding)

    def test_ac07_distinguishes_the_error_codes_get_memory_models(self):
        model = agentcore_app.boto3.client(
            "bedrock-agentcore-control",
            region_name="us-east-1",
            aws_access_key_id="testing",
            aws_secret_access_key="testing",  # pragma: allowlist secret - synthetic test credential
        ).meta.service_model
        errors = {e.name for e in model.operation_model("GetMemory").error_shapes}

        assert {"AccessDeniedException", "ResourceNotFoundException"} <= errors

    def test_memory_namespace_is_a_customer_supplied_input(self):
        # The Failed verdict is only reachable because the namespace is an
        # optional CreateMemory input: if the service required an actor-scoped
        # template, the check could never discriminate.
        model = agentcore_app.boto3.client(
            "bedrock-agentcore-control",
            region_name="us-east-1",
            aws_access_key_id="testing",
            aws_secret_access_key="testing",  # pragma: allowlist secret - synthetic test credential
        ).meta.service_model
        strategy_input = (
            model.operation_model("CreateMemory")
            .input_shape.members["memoryStrategies"]
            .member
        )
        assert strategy_input.members
        for wrapper in strategy_input.members.values():
            assert "namespaceTemplates" in wrapper.members
            assert "namespaces" in wrapper.members
            assert set(wrapper.metadata.get("required") or []) == {"name"}

    # --- AC-07 key leg: the named key is read by value (AIR-ACR-MEM-01) ---

    _CUSTOMER_KEY = {"KeyManager": "CUSTOMER", "KeyState": "Enabled"}

    @pytest.fixture(autouse=True)
    def _customer_managed_memory_key(self):
        # Every memory key in this class describes as customer managed and
        # Enabled unless a test says otherwise, so a Passed encryption verdict
        # always rests on a DescribeKey answer.
        with patch("agentcore_app.kms_client") as mock_kms:
            mock_kms.describe_key.return_value = {"KeyMetadata": self._CUSTOMER_KEY}
            yield mock_kms

    @staticmethod
    def _two_memories(mock_ac, first_key, second_key):
        mock_ac.list_memories.return_value = {
            "memories": [
                {"id": "mem-1", "name": "First"},
                {"id": "mem-2", "name": "Second"},
            ]
        }
        mock_ac.get_memory.side_effect = [
            {"memory": TestAC07MemoryConfiguration._memory_detail(encryptionKeyArn=key)}
            for key in (first_key, second_key)
        ]

    @staticmethod
    def _encryption_rows(findings):
        return [f for f in findings if f["Finding"] == "AgentCore Memory Encryption"]

    _GOOD_KEY = "arn:aws:kms:us-east-1:123456789012:key/good"
    _BAD_KEY = "arn:aws:kms:us-east-1:123456789012:key/bad"

    @pytest.mark.parametrize(
        "bad_metadata, expected",
        [
            ({"KeyManager": "AWS", "KeyState": "Enabled"}, "managed by AWS"),
            ({"KeyState": "Enabled"}, "managed by an unknown party"),
            ({"KeyManager": "CUSTOMER", "KeyState": "Disabled"}, "reports as Disabled"),
            (
                {"KeyManager": "CUSTOMER", "KeyState": "PendingDeletion"},
                "reports as PendingDeletion",
            ),
            ({"KeyManager": "CUSTOMER"}, "in an unknown state"),
        ],
    )
    @patch("agentcore_app.agentcore_client")
    def test_ac07_a_named_key_that_is_not_a_usable_customer_key_fails(
        self, mock_ac, _customer_managed_memory_key, bad_metadata, expected
    ):
        self._two_memories(mock_ac, self._GOOD_KEY, self._BAD_KEY)
        metadata = {self._GOOD_KEY: self._CUSTOMER_KEY, self._BAD_KEY: bad_metadata}
        _customer_managed_memory_key.describe_key.side_effect = lambda KeyId: {
            "KeyMetadata": metadata[KeyId]
        }

        rows = self._encryption_rows(
            extract_csv_data(agentcore_app.check_agentcore_memory_configuration())
        )

        assert [f["Status"] for f in rows] == ["Passed", "Failed"]
        assert "'First' (mem-1)" in rows[0]["Finding_Details"]
        assert "customer managed and Enabled" in rows[0]["Finding_Details"]
        assert "'Second' (mem-2)" in rows[1]["Finding_Details"]
        assert self._BAD_KEY in rows[1]["Finding_Details"]
        assert expected in rows[1]["Finding_Details"]
        assert rows[1]["Severity"] == "Medium"
        for row in rows:
            assert_finding_schema(row)

    @pytest.mark.parametrize(
        "error",
        [
            _make_client_error("AccessDeniedException", "denied"),
            _make_client_error("ThrottlingException", "slow down"),
            _make_client_error("NotFoundException", "no such key"),
        ],
    )
    @patch("agentcore_app.agentcore_client")
    def test_ac07_an_undescribed_key_is_na_not_passed(
        self, mock_ac, _customer_managed_memory_key, error
    ):
        self._two_memories(mock_ac, self._GOOD_KEY, self._BAD_KEY)

        def describe(KeyId):
            if KeyId == self._BAD_KEY:
                raise error
            return {"KeyMetadata": self._CUSTOMER_KEY}

        _customer_managed_memory_key.describe_key.side_effect = describe

        rows = self._encryption_rows(
            extract_csv_data(agentcore_app.check_agentcore_memory_configuration())
        )

        assert [f["Status"] for f in rows] == ["Passed", "N/A"]
        assert error.response["Error"]["Code"] in rows[1]["Finding_Details"]
        assert "not reported as customer managed" in rows[1]["Finding_Details"]
        assert "kms:DescribeKey" in rows[1]["Resolution"]
        assert "another account" in rows[1]["Resolution"]

    @patch("agentcore_app.agentcore_client")
    def test_ac07_a_missing_kms_client_is_na_not_passed(self, mock_ac):
        self._one_memory(mock_ac)

        with patch("agentcore_app.kms_client", None):
            rows = self._encryption_rows(
                extract_csv_data(agentcore_app.check_agentcore_memory_configuration())
            )

        assert [f["Status"] for f in rows] == ["N/A"]
        assert "KMS client is not available" in rows[0]["Finding_Details"]

    @patch("agentcore_app.agentcore_client")
    def test_ac07_a_key_shared_by_two_memories_is_described_once(
        self, mock_ac, _customer_managed_memory_key
    ):
        self._two_memories(mock_ac, self._GOOD_KEY, self._GOOD_KEY)

        rows = self._encryption_rows(
            extract_csv_data(agentcore_app.check_agentcore_memory_configuration())
        )

        assert [f["Status"] for f in rows] == ["Passed", "Passed"]
        _customer_managed_memory_key.describe_key.assert_called_once_with(
            KeyId=self._GOOD_KEY
        )

    @patch("agentcore_app.agentcore_client")
    def test_ac07_a_memory_without_a_key_still_fails_without_a_describe(
        self, mock_ac, _customer_managed_memory_key
    ):
        self._two_memories(mock_ac, self._GOOD_KEY, None)

        rows = self._encryption_rows(
            extract_csv_data(agentcore_app.check_agentcore_memory_configuration())
        )

        assert [f["Status"] for f in rows] == ["Passed", "Failed"]
        _customer_managed_memory_key.describe_key.assert_called_once_with(
            KeyId=self._GOOD_KEY
        )

    # --- AC-07 memory resource-based policy leg (AIR-ACR-MEM-01) ---

    _MEMORY_ARN = (
        "arn:aws:bedrock-agentcore:us-east-1:123456789012:memory/mem-123456789012"
    )

    @classmethod
    def _policy_rows(cls, mock_ac, policy=None, error=None):
        cls._one_memory(mock_ac, arn=cls._MEMORY_ARN)
        if error is not None:
            mock_ac.get_resource_policy.side_effect = error
        else:
            mock_ac.get_resource_policy.return_value = {"policy": policy}
        findings = extract_csv_data(
            agentcore_app.check_agentcore_memory_configuration()
        )
        return [
            f
            for f in findings
            if f["Finding"] == "AgentCore Memory Resource-Based Policy"
        ]

    @staticmethod
    def _policy(principal, condition=None):
        statement = {
            "Effect": "Allow",
            "Principal": principal,
            "Action": "bedrock-agentcore:RetrieveMemoryRecords",
            "Resource": "*",
        }
        if condition:
            statement["Condition"] = condition
        return json.dumps({"Version": "2012-10-17", "Statement": [statement]})

    @patch("agentcore_app.agentcore_client")
    def test_ac07_a_memory_policy_open_to_everyone_fails(self, mock_ac):
        rows = self._policy_rows(mock_ac, self._policy("*"))

        assert [f["Status"] for f in rows] == ["Failed"]
        assert rows[0]["Severity"] == "High"
        assert "statement 1 (*)" in rows[0]["Finding_Details"]
        mock_ac.get_resource_policy.assert_called_once_with(
            resourceArn=self._MEMORY_ARN
        )

    @patch("agentcore_app.agentcore_client")
    def test_ac07_a_memory_policy_bound_to_the_organization_passes(self, mock_ac):
        rows = self._policy_rows(
            mock_ac,
            self._policy(
                "*", {"StringEquals": {"aws:PrincipalOrgID": "o-exampleorgid"}}
            ),
        )

        assert [f["Status"] for f in rows] == ["Passed"]
        assert "no Allow statement" in rows[0]["Finding_Details"]

    @patch("agentcore_app.agentcore_client")
    def test_ac07_a_memory_without_a_policy_passes(self, mock_ac):
        rows = self._policy_rows(
            mock_ac, error=_make_client_error("ResourceNotFoundException")
        )

        assert [f["Status"] for f in rows] == ["Passed"]
        assert "no resource-based policy" in rows[0]["Finding_Details"]

    @patch("agentcore_app.agentcore_client")
    def test_ac07_an_empty_memory_policy_passes_as_no_policy(self, mock_ac):
        rows = self._policy_rows(mock_ac, "")

        assert [f["Status"] for f in rows] == ["Passed"]
        assert "no resource-based policy" in rows[0]["Finding_Details"]

    @patch("agentcore_app.agentcore_client")
    def test_ac07_a_denied_memory_policy_read_is_na_naming_the_action(self, mock_ac):
        rows = self._policy_rows(
            mock_ac, error=_make_client_error("AccessDeniedException", "denied")
        )

        assert [f["Status"] for f in rows] == ["N/A"]
        assert "AccessDeniedException" in rows[0]["Finding_Details"]
        assert "bedrock-agentcore:GetResourcePolicy" in rows[0]["Resolution"]

    @patch("agentcore_app.agentcore_client")
    def test_ac07_the_memory_policy_is_read_for_every_memory(self, mock_ac):
        other_arn = self._MEMORY_ARN.replace("mem-123456789012", "mem-2")
        mock_ac.list_memories.return_value = {
            "memories": [
                {"id": "mem-123456789012", "name": "TestMemory"},
                {"id": "mem-2", "name": "Other"},
            ]
        }
        mock_ac.get_memory.side_effect = [
            {"memory": self._memory_detail(arn=self._MEMORY_ARN)},
            {"memory": self._memory_detail(id="mem-2", arn=other_arn)},
        ]
        policies = {self._MEMORY_ARN: "", other_arn: self._policy("*")}
        mock_ac.get_resource_policy.side_effect = lambda resourceArn: {
            "policy": policies[resourceArn]
        }

        rows = [
            f
            for f in extract_csv_data(
                agentcore_app.check_agentcore_memory_configuration()
            )
            if f["Finding"] == "AgentCore Memory Resource-Based Policy"
        ]

        assert [f["Status"] for f in rows] == ["Passed", "Failed"]
        assert "'Other'" in rows[1]["Finding_Details"]


