class TestAgenticAgentCoreMapping:
    """Agentic AI AG-* rows are generated from API-backed AgentCore checks."""

    EXPECTED_AGENTIC_MAPPINGS = {
        "AC-01": "AG-15",
        "AC-02": "AG-16",
        "AC-03": "AG-17",
        "AC-04": "AG-18",
        "AC-07": "AG-19",
        "AC-08": "AG-20",
        "AC-10": "AG-21",
        "AC-11": "AG-22",
        "AC-12": "AG-23",
        "AC-14": "AG-28",
        "AC-15": "AG-29",
        "AC-16": "AG-31",
        "AC-17": "AG-32",
    }

    def test_all_agentcore_agentic_mappings_emit_expected_rows(self):
        source_findings = []
        for source_check_id in self.EXPECTED_AGENTIC_MAPPINGS:
            source_findings.append(
                {
                    "Account_ID": "123456789012",
                    "Check_ID": source_check_id,
                    "Finding": f"{source_check_id} source finding",
                    "Finding_Details": f"{source_check_id} source details",
                    "Resolution": "No action required.",
                    "Reference": "https://docs.aws.amazon.com/bedrock-agentcore/latest/devguide/security.html",
                    "Severity": "Medium",
                    "Status": "Passed",
                    "Region": "us-east-1",
                }
            )

        findings = agentcore_app.build_agentic_agentcore_security_findings(
            source_findings
        )

        assert len(findings) == len(self.EXPECTED_AGENTIC_MAPPINGS)
        actual_by_source = {}
        for finding in findings:
            details = finding["Finding_Details"]
            source_check_id = details.split("Source check ", 1)[1].split(":", 1)[0]
            actual_by_source[source_check_id] = finding

            assert finding["Status"] == "Passed"
            assert finding["Severity"] == "Medium"
            assert finding["Region"] == "us-east-1"
            assert f"Source check {source_check_id}" in details
            assert_finding_schema(finding)

        assert set(actual_by_source) == set(self.EXPECTED_AGENTIC_MAPPINGS)
        for source_check_id, expected_ag_id in self.EXPECTED_AGENTIC_MAPPINGS.items():
            assert actual_by_source[source_check_id]["Check_ID"] == expected_ag_id


def _provider(name, vault="default", kind="oauth2credentialprovider"):
    return {
        "name": name,
        "credentialProviderArn": (
            f"arn:aws:bedrock-agentcore:us-east-1:123456789012:token-vault/{vault}/"
            f"{kind}/{name}"
        ),
    }


def _ac14_key_policy(
    context="arn:aws:bedrock-agentcore:*:*:token-vault/default",
    via="bedrock-agentcore-identity.*.amazonaws.com",
    via_operator="StringLike",
    account_held=True,
    context_operator="ArnLike",
):
    """Return the AgentCore Identity guide's example vault key policy."""
    condition = {via_operator: {"kms:ViaService": via}}
    condition.setdefault(context_operator, {})[
        "kms:EncryptionContext:aws-crypto-ec:aws:bedrock-agentcore-identity:"
        "token-vault-arn"
    ] = context
    if account_held:
        condition.setdefault("StringEquals", {})["aws:ResourceAccount"] = (
            "${aws:PrincipalAccount}"
        )
    return json.dumps(
        {
            "Version": "2012-10-17",
            "Statement": [
                {
                    "Sid": "EnableRoot",
                    "Effect": "Allow",
                    "Principal": {"AWS": "arn:aws:iam::123456789012:root"},
                    "Action": "kms:*",
                    "Resource": "*",
                },
                {
                    "Sid": "BedrockAgentCoreIdentityKMSAccess",
                    "Effect": "Allow",
                    "Principal": {"AWS": "arn:aws:iam::123456789012:root"},
                    "Action": [
                        "kms:Encrypt",
                        "kms:Decrypt",
                        "kms:GenerateDataKeyWithoutPlaintext",
                    ],
                    "Resource": "*",
                    "Condition": condition,
                },
            ],
        }
    )


class TestAC14TokenVaultPopulation:
    """AC-14 reads every vault a credential provider names, and the key's state."""

    _KEY = "arn:aws:kms:us-east-1:123456789012:key/vault-key"

    @staticmethod
    def _empty_lists(mock_ac):
        mock_ac.list_oauth2_credential_providers.return_value = {
            "credentialProviders": []
        }
        mock_ac.list_api_key_credential_providers.return_value = {
            "credentialProviders": []
        }
        mock_ac.list_payment_credential_providers.return_value = {
            "credentialProviders": []
        }

    @staticmethod
    def _enabled(mock_kms, state="Enabled", manager="CUSTOMER"):
        mock_kms.describe_key.return_value = {
            "KeyMetadata": {"KeyState": state, "KeyManager": manager}
        }
        # One Identity statement per vault: a token-vault/* context binds none.
        policy = json.loads(_ac14_key_policy())
        policy["Statement"] += [
            {
                **policy["Statement"][1],
                "Condition": json.loads(
                    _ac14_key_policy(
                        context=(
                            "arn:aws:bedrock-agentcore:us-east-1:123456789012:"
                            f"token-vault/{vault}"
                        )
                    )
                )["Statement"][1]["Condition"],
            }
            for vault in ("team-vault", "pay-vault", "vault-b")
        ]
        mock_kms.get_key_policy.return_value = {"Policy": json.dumps(policy)}

    def _vaults(self, mock_ac, configs):
        def get(tokenVaultId):
            config = configs[tokenVaultId]
            if isinstance(config, Exception):
                raise config
            return {"tokenVaultId": tokenVaultId, "kmsConfiguration": config}

