    def test_one_wildcard_sink_among_scoped_ones_fails_alone(self, mock_oam, mock_orgs):
        mock_orgs.describe_organization.return_value = {
            "Organization": {"Id": "o-a1b2c3d4e5"}
        }
        second = dict(
            self._SINK,
            Arn="arn:aws:oam:us-east-1:123456789012:sink/s-2",
            Name="open-sink",
        )
