@pytest.mark.usefixtures("_member_account")
class TestAC26LogTamperEveryRegionsInvocationGroup:
    """AC-26 SCP leg: the invocation log group of every assessed Region."""

    _REGIONS = ["us-east-1", "us-west-2", "eu-west-1"]

    @pytest.fixture(autouse=True)
    def bedrock(self):
        with patch("agentcore_app.bedrock_client") as bedrock:
            bedrock.meta.region_name = "us-east-1"
            bedrock.get_model_invocation_logging_configuration.return_value = {
                "loggingConfig": {
                    "cloudWatchConfig": {"logGroupName": _INVOCATION_GROUP}
                }
            }
            yield bedrock

    def _regional(self, west=None, europe=None):
        west_client = MagicMock()
        if isinstance(west, Exception):
            west_client.get_model_invocation_logging_configuration.side_effect = west
        else:
            west_client.get_model_invocation_logging_configuration.return_value = {
                "loggingConfig": {
                    "cloudWatchConfig": {"logGroupName": west or _WEST_GROUP}
                }
            }
        europe_client = MagicMock()
        europe_client.get_model_invocation_logging_configuration.side_effect = (
            europe
            or EndpointConnectionError(
                endpoint_url="https://bedrock.eu-west-1.amazonaws.com"
            )
        )
        return {"us-west-2": west_client, "eu-west-1": europe_client}

    def _findings(self, mock_orgs, documents, clients, regions=None):
        sts = MagicMock()
        sts.get_caller_identity.return_value = {"Account": _MEMBER_ACCOUNT}
        with (
            patch("agentcore_app.boto3.client") as factory,
            patch.object(
                agentcore_app,
                "_ac26_every_region",
                lambda: agentcore_app.check_agentcore_log_tamper_scp(
                    regions or self._REGIONS
                ),
                create=True,
            ),
        ):
            factory.side_effect = lambda service, **kwargs: (
                sts if service == "sts" else clients[kwargs["region_name"]]
            )
            findings = TestSCPAttachment._run(
                self, mock_orgs, "_ac26_every_region", documents
            )
        return findings, [
            call for call in factory.call_args_list if call.args != ("sts",)
        ]

    @patch("agentcore_app.organizations_client")
    def test_a_deny_that_misses_another_regions_invocation_group_fails(self, mock_orgs):
        findings, factory = self._findings(
            mock_orgs,
            {
                "DenyLogTamper": _log_tamper_guard(
                    resource=_AGENTCORE_LOG_RESOURCES + _INVOCATION_RESOURCES
                )
            },
            self._regional(),
        )

        assert [f["Status"] for f in findings] == ["Failed"]
        assert findings[0]["Finding"] == "Log Tamper Guardrail Missing"
        assert sorted(call.kwargs["region_name"] for call in factory) == [
            "eu-west-1",
            "us-west-2",
        ]
        for call in factory:
            assert call.args == ("bedrock",)

    @patch("agentcore_app.organizations_client")
    def test_a_deny_on_every_regions_invocation_group_passes(self, mock_orgs):
        findings, _ = self._findings(
            mock_orgs,
            {
                "DenyLogTamper": _log_tamper_guard(
                    resource=_AGENTCORE_LOG_RESOURCES
                    + _INVOCATION_RESOURCES
                    + _WEST_RESOURCES
                )
            },
            self._regional(),
        )

        assert [f["Status"] for f in findings] == ["Passed"]
        assert (
            "the Bedrock model invocation log group each assessed Region"
            in (findings[0]["Finding_Details"])
        )

    @patch("agentcore_app.organizations_client")
    def test_an_unread_other_region_turns_a_pass_into_na_naming_it(self, mock_orgs):
        findings, _ = self._findings(
            mock_orgs,
            {
                "DenyLogTamper": _log_tamper_guard(
                    resource=_AGENTCORE_LOG_RESOURCES + _INVOCATION_RESOURCES
                )
            },
            self._regional(west=_make_client_error("AccessDeniedException", "denied")),
        )

        assert [f["Status"] for f in findings] == ["N/A"]
        assert findings[0]["Finding"] == "Log Tamper Guardrail Incomplete"
        details = findings[0]["Finding_Details"]
        assert "could not be read in us-west-2 (AccessDeniedException" in details
        assert "eu-west-1" not in details.split("could not be read", 1)[1]

    @patch("agentcore_app.organizations_client")
    def test_an_opted_out_region_is_skipped(self, mock_orgs):
        findings, _ = self._findings(
            mock_orgs,
            {
                "DenyLogTamper": _log_tamper_guard(
                    resource=_AGENTCORE_LOG_RESOURCES
                    + _INVOCATION_RESOURCES
                    + _WEST_RESOURCES
                )
            },
            self._regional(
                europe=_make_client_error("UnrecognizedClientException", "opt-in")
            ),
        )

        assert [f["Status"] for f in findings] == ["Passed"]

    def test_both_global_check_lists_pass_the_assessed_regions(self):
        source = textwrap.dedent(inspect.getsource(agentcore_app.lambda_handler))

        assert source.count("check_agentcore_log_tamper_scp(target_regions)") == 2
        assert source.count("check_agentcore_log_tamper_scp,") == 0


class TestAC26VendedLogDeletionProtection:
    """AC-26: vended-log groups are held to deletion protection."""

    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.logs_client")
    def test_each_vended_group_is_judged(self, mock_logs, mock_kms):
        mock_logs.describe_log_groups.side_effect = _log_group_side_effect(
            {
                "/aws/vendedlogs/bedrock-agentcore/": [
                    {
                        "logGroupName": "/aws/vendedlogs/bedrock-agentcore/memory/m1",
                        "kmsKeyId": TestAC26LogRetentionAndKeyScope._KEY,
                        "retentionInDays": 30,
                        "deletionProtectionEnabled": True,
                    },
                    {
                        "logGroupName": "/aws/vendedlogs/bedrock-agentcore/gateway/g1",
                        "kmsKeyId": TestAC26LogRetentionAndKeyScope._KEY,
                        "retentionInDays": 30,
                    },
                ]
            }
        )

        mock_kms.get_key_policy.return_value = {
            "Policy": TestAC26LogRetentionAndKeyScope._SCOPED_KEY_POLICY
        }

        findings = agentcore_app.check_agentcore_log_retention_and_key_scope()

        assert [finding["Status"] for finding in findings] == ["Passed", "Failed"]
        assert "deletion protection enabled" in findings[0]["Finding_Details"]
        assert "gateway/g1" in findings[1]["Finding_Details"]
        assert "deletion protection off" in findings[1]["Finding_Details"]
        assert "vended-log" in findings[1]["Resolution"]

    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.logs_client")
    def test_a_vended_group_with_protection_off_fails(self, mock_logs, mock_kms):
        mock_logs.describe_log_groups.side_effect = _log_group_side_effect(
            {
                "/aws/vendedlogs/bedrock-agentcore/": [
                    {
                        "logGroupName": "/aws/vendedlogs/bedrock-agentcore/memory/m1",
                        "retentionInDays": 30,
                        "deletionProtectionEnabled": False,
                    }
                ]
            }
        )

        findings = agentcore_app.check_agentcore_log_retention_and_key_scope()

        assert [finding["Status"] for finding in findings] == ["Failed"]


@pytest.mark.usefixtures("_member_account")
class TestAC01VPCPlacementSCP:
    """AC-01: attached SCPs require VPC placement and pin it to approved IDs."""

    _run = TestSCPAttachment._run

    def _findings(self, mock_orgs, documents, targets=None):
        findings = self._run(
            mock_orgs, "check_agentcore_vpc_placement_scp", documents, targets
        )
        return {f["Finding"].split(" Guardrail")[0]: f for f in findings}

    @patch("agentcore_app.organizations_client")
    def test_attached_null_and_pin_denies_pass_both_legs(self, mock_orgs):
        findings = self._findings(
            mock_orgs,
            {"RequireVpc": _vpc_null_guard(), "PinVpc": _vpc_pin_guard()},
        )

        assert findings["VPC Placement"]["Status"] == "Passed"
        assert findings["VPC Subnet Pin"]["Status"] == "Passed"
        assert findings["VPC Security Group Pin"]["Status"] == "Passed"
        assert findings["VPC Placement"]["Check_ID"] == "AC-01"

    @patch("agentcore_app.organizations_client")
    def test_a_pin_without_a_null_deny_fails_the_placement_leg(self, mock_orgs):
        # ForAnyValue on an absent key is false, so a pin alone lets a call that
        # names no subnet at all create a runtime outside the VPC.
        findings = self._findings(mock_orgs, {"PinVpc": _vpc_pin_guard()})

        assert findings["VPC Placement"]["Status"] == "Failed"
        assert findings["VPC Placement"]["Finding"].endswith("Missing")
        assert findings["VPC Subnet Pin"]["Status"] == "Passed"
        assert findings["VPC Security Group Pin"]["Status"] == "Passed"

    @pytest.mark.parametrize(
        "condition",
        [
            {"Null": {"bedrock-agentcore:subnets": "false"}},
            {
                "Null": {"bedrock-agentcore:subnets": "true"},
                "StringEquals": {"aws:PrincipalTag/team": "agents"},
            },
            {"Null": {"aws:SourceVpc": "true"}},
        ],
        ids=["null-false", "anded-tag", "other-key"],
    )
    @patch("agentcore_app.organizations_client")
    def test_a_null_deny_that_does_not_fire_on_absence_fails(
        self, mock_orgs, condition
    ):
        findings = self._findings(
            mock_orgs,
            {"RequireVpc": _vpc_null_guard(condition=condition)},
        )

        assert findings["VPC Placement"]["Status"] == "Failed"

    @patch("agentcore_app.organizations_client")
    def test_a_null_deny_on_one_key_passes(self, mock_orgs):
        findings = self._findings(
            mock_orgs,
            {
                "RequireVpc": _vpc_null_guard(
                    condition={"Null": {"bedrock-agentcore:subnets": "true"}}
                )
            },
        )

        assert findings["VPC Placement"]["Status"] == "Passed"

    @patch("agentcore_app.organizations_client")
    def test_a_tool_create_left_out_is_partial(self, mock_orgs):
        findings = self._findings(
            mock_orgs,
            {"RequireVpc": _vpc_null_guard(action=_VPC_PLACEMENT_ACTIONS[:3])},
        )

        assert findings["VPC Placement"]["Finding"] == "VPC Placement Guardrail Partial"
        assert (
            "bedrock-agentcore:CreateBrowser"
            in findings["VPC Placement"]["Finding_Details"]
        )

    @patch("agentcore_app.organizations_client")
    def test_a_regional_resource_misses_the_create_actions(self, mock_orgs):
        # The create actions carry no resource type, so only `*` reaches them;
        # a runtime ARN pattern reaches UpdateAgentRuntime alone.
        findings = self._findings(
            mock_orgs,
            {
                "RequireVpc": _vpc_null_guard(
                    resource="arn:aws:bedrock-agentcore:*:*:runtime/*"
                )
            },
        )

        assert findings["VPC Placement"]["Finding"] == "VPC Placement Guardrail Partial"
        assert (
            "bedrock-agentcore:CreateAgentRuntime"
            in findings["VPC Placement"]["Finding_Details"]
        )

    @pytest.mark.parametrize(
        "operator, values",
        [
            ("ForAnyValue:StringNotLike", ["subnet-*"]),
            ("ForAllValues:StringNotEquals", ["subnet-0a1b2c3d"]),
            ("StringNotEquals", ["subnet-0a1b2c3d"]),
        ],
        ids=["wildcard-value", "for-all-values", "no-set-operator"],
    )
    @patch("agentcore_app.organizations_client")
    def test_a_pin_that_admits_any_subnet_fails(self, mock_orgs, operator, values):
        findings = self._findings(
            mock_orgs,
            {
                "RequireVpc": _vpc_null_guard(),
                "PinVpc": _vpc_pin_guard(operator=operator, values=values),
            },
        )

        assert findings["VPC Placement"]["Status"] == "Passed"
        assert findings["VPC Subnet Pin"]["Status"] == "Failed"
        assert findings["VPC Security Group Pin"]["Status"] == "Failed"

    @patch("agentcore_app.organizations_client")
    def test_a_subnet_only_pin_leaves_the_security_group_leg_missing(self, mock_orgs):
        # A subnet fixes the VPC, not which of its security groups, and so not
        # the egress rules the runtime or tool runs with.
        findings = self._findings(
            mock_orgs,
            {"PinVpc": _vpc_pin_guard(keys=("bedrock-agentcore:subnets",))},
        )

        assert findings["VPC Subnet Pin"]["Status"] == "Passed"
        assert findings["VPC Security Group Pin"]["Status"] == "Failed"
        assert findings["VPC Security Group Pin"]["Finding"].endswith("Missing")
        assert (
            "bedrock-agentcore:securityGroups"
            in findings["VPC Security Group Pin"]["Resolution"]
        )

    @pytest.mark.parametrize(
        "condition",
        [
            {
                "ForAnyValue:StringNotEquals": {
                    "bedrock-agentcore:subnets": ["subnet-0a1b2c3d"],
                    "bedrock-agentcore:securityGroups": ["sg-0a1b2c3d"],
                }
            },
            {
                "ForAnyValue:StringNotEquals": {
                    "bedrock-agentcore:subnets": ["subnet-0a1b2c3d"]
                },
                "ForAnyValue:StringNotLike": {
                    "bedrock-agentcore:securityGroups": ["sg-0a1b2c3d"]
                },
            },
        ],
        ids=["one-block", "two-blocks"],
    )
    @patch("agentcore_app.organizations_client")
    def test_both_keys_anded_in_one_deny_pin_neither(self, mock_orgs, condition):
        # Condition entries are ANDed, so the deny fires only when a subnet and
        # a security group are both outside their lists: an approved subnet
        # with any security group, or the reverse, is allowed.
        findings = self._findings(
            mock_orgs,
            {
                "RequireVpc": _vpc_null_guard(),
                "PinVpc": [
                    {
                        "Effect": "Deny",
                        "Action": _VPC_PLACEMENT_ACTIONS,
                        "Resource": "*",
                        "Condition": condition,
                    }
                ],
            },
        )

        assert findings["VPC Placement"]["Status"] == "Passed"
        assert findings["VPC Subnet Pin"]["Status"] == "Failed"
        assert findings["VPC Security Group Pin"]["Status"] == "Failed"

    @patch("agentcore_app.organizations_client")
    def test_each_key_is_judged_per_action_across_policies(self, mock_orgs):
        findings = self._findings(
            mock_orgs,
            {
                "PinSubnets": _vpc_pin_guard(keys=("bedrock-agentcore:subnets",)),
                "PinGroups": _vpc_pin_guard(
                    keys=("bedrock-agentcore:securityGroups",),
                    action=_VPC_PLACEMENT_ACTIONS[:3],
                ),
            },
        )

        assert findings["VPC Subnet Pin"]["Status"] == "Passed"
        assert (
            findings["VPC Security Group Pin"]["Finding"]
            == "VPC Security Group Pin Guardrail Partial"
        )
        assert (
            "but not bedrock-agentcore:CreateBrowser"
            in findings["VPC Security Group Pin"]["Finding_Details"]
        )

    @patch("agentcore_app.organizations_client")
    def test_an_ifexists_pin_passes(self, mock_orgs):
        findings = self._findings(
            mock_orgs,
            {"PinVpc": _vpc_pin_guard(operator="ForAnyValue:StringNotEqualsIfExists")},
        )

        assert findings["VPC Subnet Pin"]["Status"] == "Passed"
        assert findings["VPC Security Group Pin"]["Status"] == "Passed"

    @patch("agentcore_app.organizations_client")
    def test_a_detached_pin_fails_unattached(self, mock_orgs):
        findings = self._findings(
            mock_orgs,
            {"RequireVpc": _vpc_null_guard(), "PinVpc": _vpc_pin_guard()},
            targets={"p-1": []},
        )

        assert findings["VPC Placement"]["Status"] == "Passed"
        assert (
            findings["VPC Subnet Pin"]["Finding"]
            == "VPC Subnet Pin Guardrail Unattached"
        )
        assert (
            findings["VPC Security Group Pin"]["Finding"]
            == "VPC Security Group Pin Guardrail Unattached"
        )

    @patch("agentcore_app.organizations_client")
    def test_unreadable_targets_of_the_only_guard_are_incomplete(self, mock_orgs):
        findings = self._findings(
            mock_orgs,
            {"RequireVpc": _vpc_null_guard()},
            targets={"p-0": _make_client_error("AccessDeniedException", "denied")},
        )

        assert findings["VPC Placement"]["Status"] == "N/A"
        assert findings["VPC Placement"]["Finding"].endswith("Incomplete")


class TestSCPGuardrailRegistration:
    """AC-01's and AC-26's SCP legs run once, on both cache paths."""

