class TestAC31CheckRegistration:
    """AC-31 reads a regional resource, so it runs in every scanned region."""

    def test_the_gateway_check_is_in_both_regional_tuples(self):
        assert "AC-31" in agentcore_app.REGIONAL_AGENTCORE_CHECK_IDS
        assert "AC-31" in agentcore_app.AGENTCORE_RUNTIME_CHECK_IDS

    def test_timeout_backfill_emits_the_gateway_check(self):
        findings = agentcore_app.build_agentcore_timeout_findings("us-east-1", [])
        assert "AC-31" in {finding["Check_ID"] for finding in findings}

    def test_the_handler_registers_the_gateway_check_once(self):
        source = textwrap.dedent(inspect.getsource(agentcore_app.lambda_handler))
        assert source.count("check_agentcore_gateway_inbound_allow_lists") == 1

    def test_the_check_judges_every_authorizer_type_the_api_models(self):
        # A fifth value would fall through to the N/A branch, so the three
        # groups have to account for all four the model carries today.
        credentials = {
            "region_name": "us-east-1",
            "aws_access_key_id": "testing",
            "aws_secret_access_key": "testing",  # pragma: allowlist secret - synthetic test credential
        }
        model = agentcore_app.boto3.client(
            "bedrock-agentcore-control", **credentials
        ).meta.service_model
        output = model.operation_model("GetGateway").output_shape
        modelled = set(output.members["authorizerType"].metadata["enum"])
        judged = set(agentcore_app.GATEWAY_AUTHORIZER_SIGV4_VALUES) | {
            agentcore_app.GATEWAY_AUTHORIZER_UNAUTHENTICATED_VALUE,
            agentcore_app.GATEWAY_AUTHORIZER_JWT_VALUE,
        }
        assert judged == modelled
        assert agentcore_app.GATEWAY_AUTHORIZER_JWT_VALUE not in (
            agentcore_app.GATEWAY_AUTHORIZER_SIGV4_VALUES
        )
        # The type is required on the response, so "unspecified" can only come
        # from a truncated read; the allow-lists are optional under it.
        assert "authorizerType" in output.required_members
        jwt = output.members["authorizerConfiguration"].members["customJWTAuthorizer"]
        claims = set(agentcore_app.JWT_AUTHORIZER_CALLER_CLAIMS) | set(
            agentcore_app.JWT_AUTHORIZER_OTHER_CLAIMS
        )
        assert claims <= set(jwt.members)
        assert jwt.required_members == ["discoveryUrl"]


_AC32_TRUSTED_ISSUERS = {
    "https://idp.example",
    "https://idp",
    "https://idp.example.com",
    "app-1",
}


def _ac32_full_pin(condition):
    """Add the aud and aws:SourceVpce pins AC-32 requires beside an iss pin."""
    merged = {operator: dict(block) for operator, block in condition.items()}
    merged.setdefault("ForAnyValue:StringEquals", {}).setdefault(
        "bedrock-agentcore:InboundJwtClaim/aud", "app-1"
    )
    merged.setdefault("StringEquals", {}).setdefault("aws:SourceVpce", "vpce-1")
    return merged


class _TrustedIssuers:
    """Stand in for the authorizer read, so these tests judge the conditions."""

    @pytest.fixture(autouse=True)
    def _trusted_issuers(self):
        with patch(
            "agentcore_app._jwt_authorizer_issuers",
            return_value=(_AC32_TRUSTED_ISSUERS, [], ["us-east-1"]),
        ):
            yield


class TestAC32InboundJwtIssuerConditions(_TrustedIssuers):
    """AC-32: who can trade a JWT from any issuer for a workload access token."""

    _WORKLOAD_ARN = (
        "arn:aws:bedrock-agentcore:us-east-1:123456789012:workload-identity-directory/"
        "default/workload-identity/agent-1"
    )

    @staticmethod
    def _cache(
        actions,
        condition=None,
        resource="*",
        principal="agent-role",
        effect="Allow",
    ):
        statement = {"Effect": effect, "Action": actions, "Resource": resource}
        if condition:
            statement["Condition"] = condition
        return {
            "role_permissions": {
                principal: {
                    "attached_policies": [
                        {"name": "p", "document": {"Statement": [statement]}}
                    ],
                    "inline_policies": [],
                }
            },
            "user_permissions": {},
        }

    def test_an_unpinned_exchange_fails(self):
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(["bedrock-agentcore:GetWorkloadAccessTokenForJWT"])
        )
        assert [f["Status"] for f in findings] == ["Failed"]
        assert findings[0]["Check_ID"] == "AC-32"
        assert findings[0]["Severity"] == "High"
        assert "role agent-role" in findings[0]["Finding_Details"]
        for finding in findings:
            assert_finding_schema(finding)

    @pytest.mark.parametrize(
        "condition_key, status",
        [
            # Tightened from Passed: an issuer pin alone admits a token the
            # issuer minted for any application, and reaches no network path.
            ("bedrock-agentcore:InboundJwtClaim/iss", "Failed"),
            # Inverted: these passed. Any issuer can mint a token carrying the
            # approved aud or client_id, so neither alone pins the issuer.
            ("bedrock-agentcore:InboundJwtClaim/aud", "Failed"),
            ("bedrock-agentcore:InboundJwtClaim/client_id", "Failed"),
        ],
    )
    def test_only_an_issuer_condition_passes(self, condition_key, status):
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(
                ["bedrock-agentcore:GetWorkloadAccessTokenForJWT"],
                condition={"StringEquals": {condition_key: "https://idp.example/"}},
            )
        )
        assert [f["Status"] for f in findings] == [status]
        assert "role agent-role" in findings[0]["Finding_Details"]

    @pytest.mark.parametrize(
        "condition_key",
        [
            "bedrock-agentcore:InboundJwtClaim/scope",
            "bedrock-agentcore:InboundJwtClaim/sub",
        ],
    )
    def test_a_claim_that_is_not_the_issuer_or_the_application_fails(
        self, condition_key
    ):
        # Both keys are real and both bound the exchange, so a check that counted
        # any InboundJwtClaim condition would read these as coverage. Neither
        # keeps a token from an unapproved issuer out.
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(
                ["bedrock-agentcore:CompleteResourceTokenAuth"],
                condition={"StringEquals": {condition_key: "agent/invoke"}},
            )
        )
        assert [f["Status"] for f in findings] == ["Failed"]

    def test_the_second_exchange_action_is_assessed(self):
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(["bedrock-agentcore:CompleteResourceTokenAuth"])
        )
        assert [f["Status"] for f in findings] == ["Failed"]

    def test_the_agentcore_namespace_wildcard_is_detected(self):
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(["bedrock-agentcore:*"])
        )
        assert [f["Status"] for f in findings] == ["Failed"]

    def test_a_bare_wildcard_action_is_detected(self):
        # Stricter than before: this asserted Passed with "No cached IAM role
        # or user", leaving an Action "*" grant to AC-02.
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(["*"])
        )
        assert [f["Status"] for f in findings] == ["Failed"]
        assert "role agent-role" in findings[0]["Finding_Details"]

    def test_the_token_actions_that_take_no_inbound_jwt_are_not_assessed(self):
        # IAM publishes no InboundJwtClaim key for these two, so a Failed verdict
        # on them would demand a condition that can never match. ID-10 is where
        # holding them at all is judged.
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(
                [
                    "bedrock-agentcore:GetWorkloadAccessToken",
                    "bedrock-agentcore:GetWorkloadAccessTokenForUserId",
                ]
            )
        )
        assert [f["Status"] for f in findings] == ["Passed"]
        assert "No cached IAM role or user" in findings[0]["Finding_Details"]

    def test_a_deny_statement_is_ignored(self):
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(
                ["bedrock-agentcore:GetWorkloadAccessTokenForJWT"], effect="Deny"
            )
        )
        assert [f["Status"] for f in findings] == ["Passed"]
        assert "No cached IAM role or user" in findings[0]["Finding_Details"]

    def test_another_service_is_ignored(self):
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(["sts:GetWorkloadAccessTokenForJWT"])
        )
        assert [f["Status"] for f in findings] == ["Passed"]

    def test_a_workload_identity_arn_without_a_condition_still_fails(self):
        # The workload identity is the only resource type these actions accept,
        # so naming it narrows which agent exchanges tokens and not which issuer
        # minted them.
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(
                ["bedrock-agentcore:GetWorkloadAccessTokenForJWT"],
                resource=self._WORKLOAD_ARN,
            )
        )
        assert [f["Status"] for f in findings] == ["Failed"]

    def test_a_pinned_statement_does_not_excuse_an_unpinned_one(self):
        cache = self._cache(
            ["bedrock-agentcore:GetWorkloadAccessTokenForJWT"],
            condition={
                "StringEquals": {
                    "bedrock-agentcore:InboundJwtClaim/iss": "https://idp.example/"
                }
            },
        )
        cache["role_permissions"]["agent-role"]["inline_policies"] = [
            {
                "name": "wide",
                "document": {
                    "Statement": [
                        {
                            "Effect": "Allow",
                            "Action": "bedrock-agentcore:CompleteResourceTokenAuth",
                            "Resource": "*",
                        }
                    ]
                },
            }
        ]

        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(cache)

        assert [f["Status"] for f in findings] == ["Failed"]

    def test_the_unpinned_statement_still_decides_when_it_is_read_first(self):
        # The mirror of the case above. A walker that records the last statement
        # it saw instead of latching the unpinned one gets the right answer in one
        # order and the wrong answer in the other.
        cache = self._cache(["bedrock-agentcore:GetWorkloadAccessTokenForJWT"])
        cache["role_permissions"]["agent-role"]["inline_policies"] = [
            {
                "name": "narrow",
                "document": {
                    "Statement": [
                        {
                            "Effect": "Allow",
                            "Action": "bedrock-agentcore:CompleteResourceTokenAuth",
                            "Resource": "*",
                            "Condition": {
                                "StringEquals": {
                                    "bedrock-agentcore:InboundJwtClaim/iss": (
                                        "https://idp.example/"
                                    )
                                }
                            },
                        }
                    ]
                },
            }
        ]

        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(cache)

        assert [f["Status"] for f in findings] == ["Failed"]

    def test_users_are_evaluated_alongside_roles(self):
        cache = self._cache(["bedrock-agentcore:GetWorkloadAccessTokenForJWT"])
        cache["user_permissions"] = cache["role_permissions"]
        cache["role_permissions"] = {}

        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(cache)

        assert [f["Status"] for f in findings] == ["Failed"]
        assert "user agent-role" in findings[0]["Finding_Details"]

    def test_pinned_and_unpinned_principals_are_reported_separately(self):
        cache = self._cache(["bedrock-agentcore:GetWorkloadAccessTokenForJWT"])
        cache["role_permissions"]["pinned-role"] = {
            "attached_policies": [
                {
                    "name": "p",
                    "document": {
                        "Statement": [
                            {
                                "Effect": "Allow",
                                "Action": (
                                    "bedrock-agentcore:GetWorkloadAccessTokenForJWT"
                                ),
                                "Resource": "*",
                                "Condition": _ac32_full_pin(
                                    {
                                        "StringEquals": {
                                            "bedrock-agentcore:InboundJwtClaim/iss": (
                                                "https://idp.example/"
                                            )
                                        }
                                    }
                                ),
                            }
                        ]
                    },
                }
            ],
            "inline_policies": [],
        }

        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(cache)

        assert {finding["Status"] for finding in findings} == {"Failed", "Passed"}

    def test_findings_are_tagged_global(self):
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(["bedrock-agentcore:GetWorkloadAccessTokenForJWT"])
        )
        assert all(
            finding["Region"] == agentcore_app.GLOBAL_REGION_LABEL
            for finding in findings
        )

    def test_an_empty_cache_is_na(self):
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            {"role_permissions": {}, "user_permissions": {}}
        )
        assert findings[0]["Status"] == "N/A"

    def test_an_unparseable_policy_does_not_hide_a_sibling_grant(self):
        cache = self._cache(["bedrock-agentcore:GetWorkloadAccessTokenForJWT"])
        cache["role_permissions"]["agent-role"]["inline_policies"] = [
            {"name": "broken", "document": "{not json"}
        ]

        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(cache)

        # Stricter than before: this asserted ["Failed"] alone, so the unread
        # policy went unreported.
        assert [f["Status"] for f in findings] == ["N/A", "Failed"]
        assert "role agent-role (policy broken)" in findings[0]["Finding_Details"]

    def test_an_unusable_cache_is_reported_incomplete(self):
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(None)

        assert [f["Status"] for f in findings] == ["N/A"]
        assert findings[0]["Finding"].endswith("Incomplete")

    @pytest.mark.parametrize(
        "value,status",
        [
            ("https://cognito-idp.*.amazonaws.com/*", "Failed"),
            ("https://cognito-idp.us-east-1.amazonaws.com/us-east-1_*", "Failed"),
            ("https://idp.example/tenant-?", "Failed"),
            ("https://idp.example/", "Passed"),
        ],
    )
    def test_a_partial_wildcard_under_stringlike_is_not_a_pin(self, value, status):
        # A StringLike issuer with a wildcard inside it passed as pinned,
        # though it admits every user pool or tenant the pattern spans.
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            self._cache(
                ["bedrock-agentcore:GetWorkloadAccessTokenForJWT"],
                condition=_ac32_full_pin(
                    {"StringLike": {"bedrock-agentcore:InboundJwtClaim/iss": value}}
                ),
            )
        )
        assert [f["Status"] for f in findings] == [status]

    def test_a_wildcard_issuer_role_fails_beside_a_pinned_role(self):
        cache = self._cache(
            ["bedrock-agentcore:GetWorkloadAccessTokenForJWT"],
            condition={
                "StringLike": {
                    "bedrock-agentcore:InboundJwtClaim/iss": (
                        "https://cognito-idp.*.amazonaws.com/*"
                    )
                }
            },
            principal="wide-role",
        )
        cache["role_permissions"].update(
            self._cache(
                ["bedrock-agentcore:GetWorkloadAccessTokenForJWT"],
                condition=_ac32_full_pin(
                    {
                        "StringEquals": {
                            "bedrock-agentcore:InboundJwtClaim/iss": "https://idp.example/"
                        }
                    }
                ),
                principal="pinned-role",
            )["role_permissions"]
        )

        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(cache)

        failed = [f for f in findings if f["Status"] == "Failed"]
        assert len(failed) == 1
        assert "role wide-role" in failed[0]["Finding_Details"]
        assert "pinned-role" not in failed[0]["Finding_Details"]


class TestAC32IssuerMustBePinned(_TrustedIssuers):
    """AC-32 counts an exchange as pinned only when the issuer is pinned."""

    _EXCHANGE = "bedrock-agentcore:GetWorkloadAccessTokenForJWT"
    _ISS = "bedrock-agentcore:InboundJwtClaim/iss"
    _AUD = "bedrock-agentcore:InboundJwtClaim/aud"
    _CLIENT = "bedrock-agentcore:InboundJwtClaim/client_id"

    @classmethod
    def _allow(cls, condition):
        return {
            "Effect": "Allow",
            "Action": cls._EXCHANGE,
            "Resource": "*",
            "Condition": condition,
        }

    @pytest.mark.parametrize(
        "condition",
        [
            {"StringEquals": {_AUD: "app-1"}},
            {"ForAnyValue:StringEquals": {_AUD: "app-1"}},
            {"StringEquals": {_CLIENT: "client-1"}},
            {"StringEquals": {_AUD: "app-1", _CLIENT: "client-1"}},
            {
                "StringLike": {_ISS: "https://cognito-idp.*.amazonaws.com/*"},
                "StringEquals": {_AUD: "app-1"},
            },
        ],
        ids=["aud", "any-aud", "client-id", "aud-and-client-id", "wild-iss-and-aud"],
    )
    def test_an_audience_or_client_without_an_issuer_fails(self, condition):
        # Any identity provider can mint a token whose aud or client_id carries
        # the approved value, so only an iss condition keeps another issuer out.
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            _v2_cache(
                roles={
                    "wide": _principal_with([self._allow(condition)]),
                    "narrow": _principal_with(
                        [
                            self._allow(
                                _ac32_full_pin(
                                    {"StringEquals": {self._ISS: "https://idp/"}}
                                )
                            )
                        ]
                    ),
                }
            )
        )
        failed = [f for f in findings if f["Status"] == "Failed"]
        passed = [f for f in findings if f["Status"] == "Passed"]
        assert len(failed) == 1 and len(passed) == 1
        assert "role wide" in failed[0]["Finding_Details"]
        assert "role narrow" not in failed[0]["Finding_Details"]
        assert "alone does not pin the issuer" in failed[0]["Finding_Details"]
        assert "role narrow" in passed[0]["Finding_Details"]
        assert "role wide" not in passed[0]["Finding_Details"]

    @pytest.mark.parametrize(
        "condition",
        [
            {"StringEquals": {_ISS: "https://idp/", _AUD: "app-1"}},
            {
                "StringEquals": {_ISS: "https://idp/"},
                "ForAnyValue:StringEquals": {_AUD: "app-1"},
            },
            {"StringEqualsIgnoreCase": {_ISS: "https://idp/"}},
        ],
        ids=["iss-and-aud", "iss-beside-any-aud", "iss-ignore-case"],
    )
    def test_an_issuer_condition_passes_only_with_the_other_pins(self, condition):
        # Tightened from Passed: the control pins the application and the
        # network path beside the issuer, so each condition here now fails on
        # its own and passes once the missing pins are added.
        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            _v2_cache(roles={"role": _principal_with([self._allow(condition)])})
        )
        assert [f["Status"] for f in findings] == ["Failed"]
        has_application = any(
            self._AUD in block or self._CLIENT in block for block in condition.values()
        )
        assert findings[0]["Finding"] == (
            "AgentCore Inbound JWT Network Path Unbound"
            if has_application
            else "AgentCore Inbound JWT Application Conditions Missing"
        )

        findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
            _v2_cache(
                roles={
                    "role": _principal_with([self._allow(_ac32_full_pin(condition))])
                }
            )
        )
        assert [f["Status"] for f in findings] == ["Passed"]
        assert "issuer condition" in findings[0]["Finding_Details"]


class TestAC32ApplicationNetworkAndIssuer:
    """AC-32 pins the application and network path, and compares the issuer."""

    _EXCHANGE = "bedrock-agentcore:GetWorkloadAccessTokenForJWT"
    _ISS = "bedrock-agentcore:InboundJwtClaim/iss"
    _COGNITO = "https://cognito-idp.us-west-2.amazonaws.com/us-west-2_abc"

    @classmethod
    def _role(cls, condition):
        return _principal_with(
            [
                {
                    "Effect": "Allow",
                    "Action": cls._EXCHANGE,
                    "Resource": "*",
                    "Condition": condition,
                }
            ]
        )

    @staticmethod
    def _rows(findings):
        rows = {}
        for finding in findings:
            rows.setdefault(finding["Finding"], []).append(finding)
        return rows

    @pytest.mark.parametrize(
        "network",
        [
            {"StringEqualsIfExists": {"aws:SourceVpce": "vpce-1"}},
            {"StringLike": {"aws:SourceVpce": "vpce-*"}},
            {"StringNotEquals": {"aws:SourceVpc": "vpc-other"}},
        ],
        ids=["if-exists", "wildcard", "negated"],
    )
    def test_each_missing_pin_fails_only_its_role(self, network):
        iss = {"StringEquals": {self._ISS: "https://idp.example"}}
        aud = {
            "ForAnyValue:StringEquals": {
                "bedrock-agentcore:InboundJwtClaim/aud": "app-1"
            }
        }
        with patch(
            "agentcore_app._jwt_authorizer_issuers",
            return_value=({"https://idp.example"}, [], ["us-east-1"]),
        ):
            findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
                _v2_cache(
                    roles={
                        "no-app": self._role(dict(iss, StringLike={})),
                        "no-net": self._role({**iss, **aud, **network}),
                        "full": self._role(_ac32_full_pin(iss)),
                    }
                )
            )

        rows = self._rows(findings)
        app = rows["AgentCore Inbound JWT Application Conditions Missing"]
        net = rows["AgentCore Inbound JWT Network Path Unbound"]
        passed = [f for f in findings if f["Status"] == "Passed"]
        assert [f["Status"] for f in app + net] == ["Failed", "Failed"]
        assert "role no-app" in app[0]["Finding_Details"]
        assert "role no-net" not in app[0]["Finding_Details"]
        assert "role no-net" in net[0]["Finding_Details"]
        assert "role no-app" not in net[0]["Finding_Details"]
        assert len(passed) == 1
        assert "role full" in passed[0]["Finding_Details"]
        assert "role no-" not in passed[0]["Finding_Details"]

    def test_a_pinned_issuer_is_compared_with_every_regions_authorizers(self):
        def region_client(runtimes, gateways):
            client = MagicMock()
            client.list_agent_runtimes.return_value = {
                "agentRuntimes": [{"agentRuntimeId": rid} for rid in runtimes]
            }
            client.get_agent_runtime.side_effect = lambda agentRuntimeId: runtimes[
                agentRuntimeId
            ]
            client.list_gateways.return_value = {
                "items": [{"gatewayId": gid} for gid in gateways]
            }
            client.get_gateway.side_effect = lambda gatewayIdentifier: gateways[
                gatewayIdentifier
            ]
            return client

        def jwt(url):
            return {
                "authorizerConfiguration": {
                    "customJWTAuthorizer": {"discoveryUrl": url}
                }
            }

        denied = MagicMock()
        denied.list_agent_runtimes.side_effect = ClientError(
            {"Error": {"Code": "AccessDeniedException", "Message": "no"}},
            "ListAgentRuntimes",
        )
        clients = {
            "us-east-1": region_client(
                {"rt-iam": {}},
                {"gw-1": jwt("https://idp.example/.well-known/openid-configuration")},
            ),
            "us-west-2": region_client(
                {"rt-1": jwt(f"{self._COGNITO}/.well-known/openid-configuration")}, {}
            ),
            "eu-west-1": denied,
        }
        roles = {
            "gateway-idp": self._role(
                _ac32_full_pin({"StringEquals": {self._ISS: "https://idp.example/"}})
            ),
            "west-pool": self._role(
                _ac32_full_pin({"StringEquals": {self._ISS: self._COGNITO}})
            ),
            "stranger": self._role(
                _ac32_full_pin({"StringEquals": {self._ISS: "https://other.example"}})
            ),
        }
        with (
            patch("agentcore_app.agentcore_client", None),
            patch(
                "agentcore_app.boto3.client",
                side_effect=lambda service, config=None, region_name=None: clients[
                    region_name
                ],
            ),
        ):
            findings = agentcore_app.check_agentcore_inbound_jwt_issuer_conditions(
                _v2_cache(roles=roles), ["us-east-1", "us-west-2", "eu-west-1"]
            )

        rows = self._rows(findings)
        passed = [f for f in findings if f["Status"] == "Passed"]
        assert len(passed) == 1
        assert "role gateway-idp" in passed[0]["Finding_Details"]
        assert "role west-pool" in passed[0]["Finding_Details"]
        assert "stranger" not in passed[0]["Finding_Details"]
        unapproved = rows["AgentCore Inbound JWT Issuer Unapproved"]
        assert [f["Status"] for f in unapproved] == ["N/A"]
        details = unapproved[0]["Finding_Details"]
        assert "role stranger (https://other.example)" in details
        assert "gateway-idp" not in details
        assert "eu-west-1" in details
        for finding in findings:
            assert_finding_schema(finding)

    def test_the_handler_passes_every_assessed_region(self):
        source = textwrap.dedent(inspect.getsource(agentcore_app.lambda_handler))
        call = next(
            node
            for node in ast.walk(ast.parse(source))
            if isinstance(node, ast.Call)
            and ast.unparse(node.func)
            == "check_agentcore_inbound_jwt_issuer_conditions"
        )
        assert len(call.args) == 2
        assert "target_regions" in ast.unparse(call.args[1])


_APPROVED_DISCOVERY_URL = (
    "https://login.example.com/oauth2/default/.well-known/openid-configuration"
)


def _discovery_url_guard(operator="StringNotEquals", value=None, action=None):
    return [
        {
            "Effect": "Deny",
            "Action": action or _GATEWAY_WRITE,
            "Resource": "*",
            "Condition": {
                operator: {
                    "bedrock-agentcore:DiscoveryUrl": value or _APPROVED_DISCOVERY_URL
                }
            },
        }
    ]


@pytest.mark.usefixtures("_member_account")
class TestAC32GatewayDiscoveryUrlSCP:
    """AIR-ACR-ID-11: an attached SCP denies CreateGateway and UpdateGateway when
    bedrock-agentcore:DiscoveryUrl names an identity provider it does not list."""

    _run = TestSCPAttachment._run

    def _finding(self, mock_orgs, documents, targets=None):
        (finding,) = self._run(
            mock_orgs, "check_agentcore_gateway_discovery_url_scp", documents, targets
        )
        assert finding["Check_ID"] == "AC-32"
        return finding

    @pytest.mark.parametrize("decoy_first", [False, True])
    @patch("agentcore_app.organizations_client")
    def test_an_attached_allow_list_passes(self, mock_orgs, decoy_first):
        guard = {"EnforceGatewayIdP": _discovery_url_guard()}
        decoy = {"DenyNone": _gateway_guard()}
        documents = {**decoy, **guard} if decoy_first else {**guard, **decoy}
        finding = self._finding(mock_orgs, documents)
        assert finding["Status"] == "Passed"
        assert "EnforceGatewayIdP" in finding["Finding_Details"]
        assert "DenyNone" not in finding["Finding_Details"]
        assert "was not compared with the gateways'" in finding["Finding_Details"]

    @patch("agentcore_app.organizations_client")
    def test_a_deny_list_of_one_bad_url_is_ineffective(self, mock_orgs):
        # A StringEquals Deny on one known-bad issuer admits every issuer it does
        # not name, so it is reported and not credited.
        finding = self._finding(
            mock_orgs,
            {
                "DenyOneIssuer": _discovery_url_guard(
                    operator="StringEquals",
                    value="https://evil.example.com/.well-known/openid-configuration",
                )
            },
        )
        assert finding["Status"] == "Failed"
        assert finding["Finding"].endswith("Ineffective")
        assert "DenyOneIssuer" in finding["Finding_Details"]

    @patch("agentcore_app.organizations_client")
    def test_a_create_only_deny_is_partial(self, mock_orgs):
        finding = self._finding(
            mock_orgs,
            {"CreateOnly": _discovery_url_guard(action=_GATEWAY_WRITE[:1])},
        )
        assert finding["Status"] == "Failed"
        assert finding["Finding"].endswith("Partial")
        assert "UpdateGateway" in finding["Finding_Details"]

    @patch("agentcore_app.organizations_client")
    def test_a_regional_resource_scope_is_not_credited(self, mock_orgs):
        guard = _discovery_url_guard()
        guard[0]["Resource"] = "arn:aws:bedrock-agentcore:us-east-1:*:gateway/*"
        finding = self._finding(mock_orgs, {"OneRegion": guard})
        assert finding["Status"] == "Failed"

    @patch("agentcore_app.organizations_client")
    def test_an_unattached_guard_fails_unattached(self, mock_orgs):
        finding = self._finding(
            mock_orgs,
            {"EnforceGatewayIdP": _discovery_url_guard()},
            targets={"p-0": [{"TargetId": _OTHER_OU, "Type": "ORGANIZATIONAL_UNIT"}]},
        )
        assert finding["Status"] == "Failed"
        assert finding["Finding"].endswith("Unattached")

    @patch("agentcore_app.organizations_client")
    def test_no_guard_fails_missing(self, mock_orgs):
        finding = self._finding(mock_orgs, {"DenyNone": _gateway_guard()})
        assert finding["Status"] == "Failed"
        assert finding["Finding"].endswith("Missing")

    def test_the_handler_registers_the_leg_on_both_cache_paths(self):
        source = textwrap.dedent(inspect.getsource(agentcore_app.lambda_handler))
        registrations = [
            node
            for node in ast.walk(ast.parse(source))
            if isinstance(node, ast.Assign)
            and any(
                isinstance(target, ast.Name) and target.id == "global_checks"
                for target in node.targets
            )
        ]
        assert len(registrations) == 2
        for registration in registrations:
            assert "check_agentcore_gateway_discovery_url_scp" in ast.unparse(
                registration.value
            )

    def test_the_condition_key_is_spelled_as_the_reference_declares(self):
        assert agentcore_app.GATEWAY_DISCOVERY_URL_CONDITION_KEY == (
            "bedrock-agentcore:discoveryurl"
        )


class TestAC32CheckRegistration:
    """AC-32 reads the global IAM cache, so it runs once and not per region."""

    def test_the_cache_check_is_not_in_the_regional_tuples(self):
        assert "AC-32" not in agentcore_app.REGIONAL_AGENTCORE_CHECK_IDS
        assert "AC-32" not in agentcore_app.AGENTCORE_RUNTIME_CHECK_IDS

    def test_the_handler_registers_the_check_on_the_cached_path_only(self):
        source = textwrap.dedent(inspect.getsource(agentcore_app.lambda_handler))
        registrations = [
            node
            for node in ast.walk(ast.parse(source))
            if isinstance(node, ast.Assign)
            and any(
                isinstance(target, ast.Name) and target.id == "global_checks"
                for target in node.targets
            )
        ]
        assert len(registrations) == 2
        registered = [
            "check_agentcore_inbound_jwt_issuer_conditions"
            in ast.unparse(registration.value)
            for registration in registrations
        ]
        # The first list is the path taken when the cache is missing, where this
        # check has nothing to read; the second is the cached path.
        assert registered == [False, True]

    def test_a_missing_cache_reports_the_check_incomplete(self):
        source = textwrap.dedent(inspect.getsource(agentcore_app.lambda_handler))
        assert '("AC-32", "AgentCore Inbound JWT Issuer Conditions")' in source

    def test_the_exchange_actions_name_real_api_operations(self):
        # A typo here would narrow the check to nothing and report every account
        # as having no token-exchange grant.
        model = agentcore_app.boto3.client(
            "bedrock-agentcore",
            region_name="us-east-1",
            aws_access_key_id="testing",
            aws_secret_access_key="testing",  # pragma: allowlist secret - synthetic test credential
        ).meta.service_model
        operations = {name.lower() for name in model.operation_names}
        assert set(agentcore_app.INBOUND_JWT_EXCHANGE_ACTIONS) <= operations
        # The two token actions that accept no inbound JWT exist as well, so
        # their absence from the tuple is a scoping decision and not a typo.
        assert {
            "getworkloadaccesstoken",
            "getworkloadaccesstokenforuserid",
        } <= operations
        assert {
            "getworkloadaccesstoken",
            "getworkloadaccesstokenforuserid",
        }.isdisjoint(agentcore_app.INBOUND_JWT_EXCHANGE_ACTIONS)

    def test_the_condition_keys_are_matchable_and_exclude_the_weaker_claims(self):
        # _statement_condition_keys lowercases, so an uppercased entry here would
        # never match and every grant would read as unpinned.
        # aud and client_id name the application, which any issuer can mint.
        key = agentcore_app.INBOUND_JWT_ISSUER_KEY
        assert key == key.lower()
        assert key == "bedrock-agentcore:inboundjwtclaim/iss"


