class TestAC36SetOperatorsAndRuleTargets:
    """AC-36 credits no ForAllValues condition on a key a request can omit,
    and no EventBridge rule that has no target."""

    _base = TestAC36KeyLossAlarmAndServiceBounds()

    @staticmethod
    def _for_all_values(statements, key):
        """Move `key` in every statement's StringEquals or StringLike under the
        ForAllValues form of the same operator."""
        moved = []
        for statement in statements:
            condition = {
                operator: dict(entries)
                for operator, entries in statement.get("Condition", {}).items()
            }
            for operator in ("StringEquals", "StringLike"):
                if key in condition.get(operator, {}):
                    value = condition[operator].pop(key)
                    condition.setdefault(f"ForAllValues:{operator}", {})[key] = value
            moved.append({**statement, "Condition": condition})
        return moved

    @pytest.mark.parametrize(
        "key, operator, status",
        [
            ("kms:ViaService", "ForAllValues", "Failed"),
            ("kms:ViaService", "ForAnyValue", "Passed"),
            (_ENGINE_CONTEXT_KEY, "ForAllValues", "Failed"),
            (_ENGINE_CONTEXT_KEY, "ForAnyValue", "Passed"),
        ],
        ids=["via-all", "via-any", "context-all", "context-any"],
    )
    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.agentcore_client")
    def test_for_all_values_on_a_key_a_request_can_omit_scopes_nothing(
        self, mock_ac, mock_kms, key, operator, status
    ):
        # ForAllValues is true for a request without the key, so a direct
        # kms:Decrypt call, which carries no kms:ViaService, passes it.
        # ForAnyValue is false for such a request, so it scopes as the plain
        # operator does.
        statements = self._for_all_values(_engine_service_use(), key)
        if operator == "ForAnyValue":
            statements = [
                {
                    **statement,
                    "Condition": {
                        name.replace("ForAllValues:", "ForAnyValue:"): entries
                        for name, entries in statement["Condition"].items()
                    },
                }
                for statement in statements
            ]
        findings = self._base._run(
            mock_ac, mock_kms, statements=[self._base._ADMIN, *statements]
        )

        assert [f["Status"] for f in findings] == [status]
        if key == "kms:ViaService" and status == "Failed":
            assert (
                "kms:CreateGrant only with kms:ViaService"
                in findings[0]["Finding_Details"]
            )

    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.agentcore_client")
    def test_one_engine_with_a_for_all_values_scope_fails_alone(
        self, mock_ac, mock_kms
    ):
        findings = self._base._run(
            mock_ac,
            mock_kms,
            engines=("pe-1", "pe-2"),
            policies={
                "pe-1": [self._base._ADMIN, *_engine_service_use()],
                "pe-2": [
                    self._base._ADMIN,
                    *self._for_all_values(_engine_service_use(), "kms:ViaService"),
                ],
            },
        )

        assert [f["Status"] for f in findings] == ["Passed", "Failed"]
        assert "pe-2" in findings[1]["Finding_Details"]

    @pytest.mark.parametrize(
        "targets, status",
        [({"kms-key-loss": []}, "Failed"), (None, "Passed")],
        ids=["no-target", "sns-target"],
    )
    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.agentcore_client")
    def test_a_rule_with_no_target_raises_nothing(
        self, mock_ac, mock_kms, targets, status
    ):
        events = _key_loss_events(_key_loss_rule(), targets=targets)
        findings = self._base._run(
            mock_ac,
            mock_kms,
            events=events,
            logs=self._base._logs(),
            cloudwatch=self._base._cloudwatch(),
        )

        assert [f["Status"] for f in findings] == [status]
        events.list_targets_by_rule.assert_called_with(Rule="kms-key-loss")
        if status == "Failed":
            assert "has no target" in findings[0]["Finding_Details"]

    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.agentcore_client")
    def test_a_targeted_rule_after_an_untargeted_one_is_credited(
        self, mock_ac, mock_kms
    ):
        events = _key_loss_events(
            _key_loss_rule(name="first"),
            _key_loss_rule(name="second"),
            targets={"first": []},
        )
        findings = self._base._run(mock_ac, mock_kms, events=events)

        assert [f["Status"] for f in findings] == ["Passed"]
        assert "enabled EventBridge rule second" in findings[0]["Finding_Details"]

    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.agentcore_client")
    def test_unlistable_targets_are_reported_unread(self, mock_ac, mock_kms):
        events = _key_loss_events(_key_loss_rule())
        events.list_targets_by_rule.side_effect = _make_client_error(
            "AccessDeniedException", "denied"
        )
        findings = self._base._run(
            mock_ac,
            mock_kms,
            events=events,
            logs=self._base._logs(),
            cloudwatch=self._base._cloudwatch(),
        )

        assert [f["Status"] for f in findings] == ["N/A"]
        assert "events:ListTargetsByRule" in findings[0]["Finding_Details"]


class TestAC36CheckRegistration:
    """AC-36 reads regional policy engines and their regional keys."""

    def test_the_key_scope_check_is_in_both_regional_tuples(self):
        assert "AC-36" in agentcore_app.REGIONAL_AGENTCORE_CHECK_IDS
        assert "AC-36" in agentcore_app.AGENTCORE_RUNTIME_CHECK_IDS

    def test_timeout_backfill_emits_the_key_scope_check(self):
        findings = agentcore_app.build_agentcore_timeout_findings("us-east-1", [])
        assert "AC-36" in {finding["Check_ID"] for finding in findings}

    def test_the_handler_registers_the_key_scope_check_once(self):
        source = textwrap.dedent(inspect.getsource(agentcore_app.lambda_handler))
        assert source.count("check_agentcore_policy_engine_key_scope") == 1

    def test_the_key_can_be_named_at_creation_and_never_changed(self):
        # The check asserts the key policy because the key itself is immutable:
        # if UpdatePolicyEngine took a key, a wrong key would be remediable
        # without touching the key policy at all.
        model = agentcore_app.boto3.client(
            "bedrock-agentcore-control",
            region_name="us-east-1",
            aws_access_key_id="testing",
            aws_secret_access_key="testing",  # pragma: allowlist secret - synthetic test credential
        ).meta.service_model
        assert (
            "encryptionKeyArn"
            in model.operation_model("CreatePolicyEngine").input_shape.members
        )
        assert (
            "encryptionKeyArn"
            not in model.operation_model("UpdatePolicyEngine").input_shape.members
        )
        assert (
            "encryptionKeyArn"
            in model.operation_model("GetPolicyEngine").output_shape.members
        )

    def test_every_destroying_action_is_one_kms_models(self):
        # A misspelled action here would silently never match a key policy.
        model = agentcore_app.boto3.client(
            "kms",
            region_name="us-east-1",
            aws_access_key_id="testing",
            aws_secret_access_key="testing",  # pragma: allowlist secret - synthetic test credential
        ).meta.service_model
        operations = {name.lower() for name in model.operation_names}
        assert set(agentcore_app.KMS_KEY_DISABLING_ACTIONS) <= operations


@pytest.mark.usefixtures("_standalone_account")
class TestAC37PolicyGuardrailWiring:
    """AC-37: a guardrail policy needs a gateway role that can call the guardrail."""

    _GATEWAYS = [{"gatewayId": "gw-1", "name": "Support"}]
    _ROLE_ARN = "arn:aws:iam::123456789012:role/GatewayExecution"
    # The API spells the action with capitals; the module lowercases patterns to
    # compare them, so a role written the way the console writes it must match.
    _GRANTING_ROLE = {
        "role_permissions": {
            "GatewayExecution": {
                "attached_policies": [
                    {
                        "policy_name": "GuardrailChecks",
                        "document": {
                            "Statement": [
                                {
                                    "Effect": "Allow",
                                    "Action": ["bedrock:InvokeGuardrailChecks"],
                                    # Stricter than before, when a guardrail ARN
                                    # was credited: the action has no resource
                                    # type, so only "*" grants it.
                                    "Resource": "*",
                                }
                            ]
                        },
                    }
                ]
            }
        }
    }
    _SILENT_ROLE = {
        "role_permissions": {
            "GatewayExecution": {
                "inline_policies": [
                    {
                        "policy_name": "InvokeOnly",
                        "document": {
                            "Statement": [
                                {
                                    "Effect": "Allow",
                                    "Action": "bedrock:InvokeModel",
                                    "Resource": "*",
                                }
                            ]
                        },
                    }
                ]
            }
        }
    }

    def _gateway_detail(self, **kwargs):
        return _policy_engine_gateway(roleArn=self._ROLE_ARN)

    @patch("agentcore_app.agentcore_client")
    def test_a_granted_role_passes(self, mock_ac):
        mock_ac.list_gateways.return_value = {"items": self._GATEWAYS}
        mock_ac.get_gateway.side_effect = self._gateway_detail
        mock_ac.list_policies.return_value = {
            "policies": [_cedar_policy("block_injection", _GUARDRAIL_FORBID)]
        }

        findings = agentcore_app.check_agentcore_policy_guardrail_wiring(
            self._GRANTING_ROLE
        )

        assert len(findings) == 1
        assert findings[0]["Check_ID"] == "AC-37"
        assert findings[0]["Status"] == "Passed"
        assert "block_injection" in findings[0]["Finding_Details"]
        assert "bedrock:InvokeGuardrailChecks" in findings[0]["Finding_Details"]
        assert "non-deterministic" in findings[0]["Resolution"]
        assert_finding_schema(findings[0])

    @patch("agentcore_app.agentcore_client")
    def test_a_role_without_the_grant_fails(self, mock_ac):
        mock_ac.list_gateways.return_value = {"items": self._GATEWAYS}
        mock_ac.get_gateway.side_effect = self._gateway_detail
        mock_ac.list_policies.return_value = {
            "policies": [_cedar_policy("block_injection", _GUARDRAIL_FORBID)]
        }

        findings = agentcore_app.check_agentcore_policy_guardrail_wiring(
            self._SILENT_ROLE
        )

        assert findings[0]["Status"] == "Failed"
        assert findings[0]["Severity"] == "High"
        assert findings[0]["Finding"].endswith("Incomplete")
        assert "forward access session" in findings[0]["Finding_Details"]
        assert "fails open or closed" in findings[0]["Finding_Details"]
        assert_finding_schema(findings[0])

    @patch("agentcore_app.agentcore_client")
    def test_a_wildcard_grant_reaches_the_guardrail_call(self, mock_ac):
        mock_ac.list_gateways.return_value = {"items": self._GATEWAYS}
        mock_ac.get_gateway.side_effect = self._gateway_detail
        mock_ac.list_policies.return_value = {
            "policies": [_cedar_policy("block_injection", _GUARDRAIL_FORBID)]
        }

        findings = agentcore_app.check_agentcore_policy_guardrail_wiring(
            {
                "role_permissions": {
                    "GatewayExecution": {
                        "inline_policies": [
                            {
                                "policy_name": "InvokeAnything",
                                "document": {
                                    "Statement": [
                                        {
                                            "Effect": "Allow",
                                            "Action": "bedrock:Invoke*",
                                            "Resource": "*",
                                        }
                                    ]
                                },
                            }
                        ]
                    }
                }
            }
        )

        assert findings[0]["Status"] == "Passed"

    @patch("agentcore_app.agentcore_client")
    def test_a_gateway_with_no_guardrail_policy_is_na_and_names_the_owner(
        self, mock_ac
    ):
        mock_ac.list_gateways.return_value = {"items": self._GATEWAYS}
        mock_ac.get_gateway.side_effect = self._gateway_detail
        mock_ac.list_policies.return_value = {
            "policies": [_cedar_policy("scoped", _SCOPED_PERMIT)]
        }

        findings = agentcore_app.check_agentcore_policy_guardrail_wiring(
            self._SILENT_ROLE
        )

        assert [finding["Status"] for finding in findings] == ["N/A"]
        assert "which no API reports" in findings[0]["Finding_Details"]
        assert "record the decision either way" in findings[0]["Resolution"]

    @patch("agentcore_app.agentcore_client")
    def test_a_temporal_condition_is_not_a_guardrail_condition(self, mock_ac):
        mock_ac.list_gateways.return_value = {"items": self._GATEWAYS}
        mock_ac.get_gateway.side_effect = self._gateway_detail
        mock_ac.list_policies.return_value = {
            "policies": [_cedar_policy("spend_cap", _TEMPORAL_PERMIT)]
        }

        findings = agentcore_app.check_agentcore_policy_guardrail_wiring(
            self._GRANTING_ROLE
        )

