        mock_ac.list_online_evaluation_configs.side_effect = ClientError(
            {"Error": {"Code": "AccessDeniedException"}}, "ListOnlineEvaluationConfigs"
        )

        findings = agentcore_app.check_agentcore_evaluation_role_trust()

