# ===================================================================
# AC-08 data-path endpoints
# ===================================================================
class TestAC08DataPathEndpointScope:
    """AC-08 also judges the S3, DynamoDB and SageMaker endpoints."""

    _DEFAULT_POLICY = json.dumps(
        {
            "Statement": [
                {
                    "Effect": "Allow",
                    "Principal": "*",
                    "Action": "*",
                    "Resource": "*",
                }
            ]
        }
    )
    _SCOPED_POLICY = json.dumps(
        {
            "Statement": [
                {
                    "Effect": "Allow",
                    "Principal": {"AWS": "arn:aws:iam::123456789012:role/app"},
                    "Action": "bedrock-agentcore:InvokeAgentRuntime",
                    "Resource": "*",
                }
            ]
        }
    )

    def _agentcore_endpoint(self):
        return {
            "VpcEndpointId": "vpce-agentcore",
            "VpcId": "vpc-1",
            "State": "available",
            "VpcEndpointType": "Interface",
            "ServiceName": "com.amazonaws.us-east-1.bedrock-agentcore",
            "PolicyDocument": self._SCOPED_POLICY,
            "PrivateDnsEnabled": True,
            "Groups": [{"GroupId": "sg-closed"}],
        }

    def _gateway_endpoint(self, endpoint_id="vpce-s3", vpc_id="vpc-1", service="s3"):
        return {
            "VpcEndpointId": endpoint_id,
            "VpcId": vpc_id,
            "State": "available",
            "VpcEndpointType": "Gateway",
            "ServiceName": f"com.amazonaws.us-east-1.{service}",
            "PolicyDocument": self._DEFAULT_POLICY,
        }

    def _wire(self, mock_ac, mock_ec2, endpoints):
        mock_ac.list_agent_runtimes.return_value = {
            "agentRuntimes": [{"agentRuntimeId": "rt-1"}]
        }
        mock_ec2.describe_vpcs.return_value = {
            "Vpcs": [{"VpcId": "vpc-1"}, {"VpcId": "vpc-2"}]
        }
        mock_ec2.describe_vpc_endpoints.return_value = {"VpcEndpoints": endpoints}
        mock_ec2.describe_security_groups.return_value = {
            "SecurityGroups": [
                {
                    "GroupId": "sg-closed",
                    "IpPermissions": [{"IpRanges": [{"CidrIp": "10.0.0.0/16"}]}],
                }
            ]
        }

    def _naming(self, findings, token):
        return [finding for finding in findings if token in finding["Finding_Details"]]

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_an_s3_gateway_endpoint_in_an_agentcore_vpc_is_judged(
        self, mock_ac, mock_ec2
    ):
        """The default S3 endpoint policy in an AgentCore VPC is reported.

        AC-08 matched only endpoint service names containing "agentcore", so the
        bucket path an agent reads its inputs and writes its outputs through was
        never judged: without the widened match this finding does not exist.
        """
        self._wire(
            mock_ac, mock_ec2, [self._agentcore_endpoint(), self._gateway_endpoint()]
        )

        findings = agentcore_app.check_agentcore_vpc_endpoints()
        unrestricted = [
            finding
            for finding in findings
            if finding["Finding"] == "AgentCore VPC Endpoint Policy Unrestricted"
        ]

        assert len(unrestricted) == 1
        assert unrestricted[0]["Status"] == "Failed"
        assert unrestricted[0]["Severity"] == "Medium"
        assert "vpce-s3" in unrestricted[0]["Finding_Details"]
        assert "com.amazonaws.us-east-1.s3" in unrestricted[0]["Finding_Details"]
        assert "vpc-1" in unrestricted[0]["Finding_Details"]
        for finding in findings:
            assert finding["Check_ID"] == "AC-08"
            assert_finding_schema(finding)

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_a_gateway_endpoint_is_not_failed_for_private_dns(self, mock_ac, mock_ec2):
        # A gateway endpoint has no private DNS setting, so the absent value is
        # not a disabled one.
        self._wire(
            mock_ac, mock_ec2, [self._agentcore_endpoint(), self._gateway_endpoint()]
        )

        findings = agentcore_app.check_agentcore_vpc_endpoints()
        private_dns = [
            finding for finding in findings if "Private DNS" in finding["Finding"]
        ]

        assert [finding["Status"] for finding in private_dns] == ["Passed"]
        assert "vpce-agentcore" in private_dns[0]["Finding_Details"]
        assert not self._naming(private_dns, "vpce-s3")
        # No security group means no inbound rule to judge either.
        network = [
            finding for finding in findings if "Network Scope" in finding["Finding"]
        ]
        assert not self._naming(network, "vpce-s3")

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_a_data_path_endpoint_outside_an_agentcore_vpc_is_not_judged(
        self, mock_ac, mock_ec2
    ):
        # An S3 endpoint in a VPC that hosts no AgentCore endpoint belongs to
        # some other workload, and AC-08 is not the check that judges it.
        self._wire(
            mock_ac,
            mock_ec2,
            [
                self._agentcore_endpoint(),
                self._gateway_endpoint(endpoint_id="vpce-s3-other", vpc_id="vpc-2"),
            ],
        )

        findings = agentcore_app.check_agentcore_vpc_endpoints()

        assert not self._naming(findings, "vpce-s3-other")
        assert not self._naming(findings, "vpc-2")

    def _wire_hosted(self, mock_ac, mock_ec2):
        """Runtime rt-1 runs in subnet-b of vpc-2, which holds an S3 endpoint
        and no AgentCore endpoint; vpc-3 hosts nothing and holds another."""
        self._wire(
            mock_ac,
            mock_ec2,
            [
                self._agentcore_endpoint(),
                self._gateway_endpoint(endpoint_id="vpce-s3-hosted", vpc_id="vpc-2"),
                self._gateway_endpoint(endpoint_id="vpce-s3-other", vpc_id="vpc-3"),
            ],
        )
        mock_ac.get_agent_runtime.return_value = {
            "agentRuntimeId": "rt-1",
            "networkConfiguration": {
                "networkMode": "VPC",
                "networkModeConfig": {"subnets": ["subnet-b"]},
            },
        }
        mock_ac.list_agent_runtime_versions.return_value = {"agentRuntimes": []}
        mock_ac.list_code_interpreters.return_value = {"codeInterpreterSummaries": []}
        mock_ac.list_browsers.return_value = {"browserSummaries": []}
        mock_ec2.describe_subnets.return_value = {
            "Subnets": [{"SubnetId": "subnet-b", "VpcId": "vpc-2"}]
        }

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_a_data_path_endpoint_in_a_hosting_vpc_is_judged(self, mock_ac, mock_ec2):
        # A VPC-mode runtime reads its data through the S3 endpoint of the VPC
        # it runs in, whether or not that VPC also holds an AgentCore endpoint.
        self._wire_hosted(mock_ac, mock_ec2)

        findings = agentcore_app.check_agentcore_vpc_endpoints()
        hosted = self._naming(findings, "vpce-s3-hosted")

        assert [finding["Finding"] for finding in hosted] == [
            "AgentCore VPC Endpoint Policy Unrestricted"
        ]
        assert hosted[0]["Status"] == "Failed"
        assert not self._naming(findings, "vpce-s3-other")

    def _wire_tools_only(
        self, mock_ac, mock_ec2, network_mode="VPC", groups=("sg-tool",)
    ):
        """No runtime or gateway; Code Interpreter ci-1 runs in subnet-tool of
        vpc-2, which holds an S3 endpoint; vpc-3 hosts nothing and holds
        another."""
        self._wire_hosted(mock_ac, mock_ec2)
        mock_ac.list_agent_runtimes.return_value = {"agentRuntimes": []}
        mock_ac.list_gateways.return_value = {"items": []}
        _wire_tools(
            mock_ac,
            interpreters=[
                _code_interpreter(network_mode=network_mode, security_groups=groups)
            ],
        )
        mock_ec2.describe_subnets.return_value = {
            "Subnets": [{"SubnetId": "subnet-tool", "VpcId": "vpc-2"}]
        }

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_a_tools_only_vpc_has_its_data_path_endpoints_judged(
        self, mock_ac, mock_ec2
    ):
        # A VPC-mode Code Interpreter reaches S3 through its own VPC's endpoint
        # even when the region holds no runtime or gateway to call through an
        # AgentCore endpoint, so the presence legs stay N/A and the data path
        # is still judged.
        self._wire_tools_only(mock_ac, mock_ec2)

        findings = agentcore_app.check_agentcore_vpc_endpoints()
        hosted = self._naming(findings, "vpce-s3-hosted")

        assert [finding["Finding"] for finding in hosted] == [
            "AgentCore VPC Endpoint Policy Unrestricted"
        ]
        assert hosted[0]["Status"] == "Failed"
        assert not self._naming(findings, "vpce-s3-other")
        presence = [
            f for f in findings if f["Finding"] == "AgentCore VPC Endpoints Check"
        ]
        assert [f["Status"] for f in presence] == ["N/A"]
        assert "no AgentCore endpoint is required" in presence[0]["Finding_Details"]
        assert not [f for f in findings if "Missing" in f["Finding"]]

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_tools_outside_a_vpc_still_find_no_agentcore_resources(
        self, mock_ac, mock_ec2
    ):
        # A PUBLIC tool reports no vpcConfig.
        self._wire_tools_only(mock_ac, mock_ec2, network_mode="PUBLIC", groups=None)

        findings = agentcore_app.check_agentcore_vpc_endpoints()

        assert len(findings) == 1
        assert findings[0]["Status"] == "N/A"
        assert findings[0]["Finding_Details"] == "No AgentCore resources found"

    @pytest.mark.parametrize(
        "denied, action",
        [
            ("get_agent_runtime", "bedrock-agentcore:GetAgentRuntime"),
            ("describe_subnets", "ec2:DescribeSubnets"),
        ],
    )
    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_an_unread_hosting_vpc_is_na(self, mock_ac, mock_ec2, denied, action):
        self._wire_hosted(mock_ac, mock_ec2)
        client = mock_ec2 if denied == "describe_subnets" else mock_ac
        getattr(client, denied).side_effect = _make_client_error(
            "AccessDeniedException", "denied"
        )

        findings = agentcore_app.check_agentcore_vpc_endpoints()
        unread = [
            finding
            for finding in findings
            if "data-path endpoints" in finding["Finding_Details"]
        ]

        assert [finding["Status"] for finding in unread] == ["N/A"]
        assert unread[0]["Finding"] == "AgentCore VPC Endpoint Policy"
        assert unread[0]["Resolution"] == f"Grant {action} and retry."
        assert not self._naming(findings, "vpce-s3-hosted")

    @pytest.mark.parametrize(
        "service", ["dynamodb", "sagemaker.api", "sagemaker.runtime"]
    )
    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_the_other_data_path_services_are_judged(self, mock_ac, mock_ec2, service):
        self._wire(
            mock_ac,
            mock_ec2,
            [
                self._agentcore_endpoint(),
                self._gateway_endpoint(endpoint_id="vpce-data", service=service),
            ],
        )

        findings = agentcore_app.check_agentcore_vpc_endpoints()
        judged = self._naming(findings, "vpce-data")

        assert len(judged) == 1
        assert judged[0]["Status"] == "Failed"
        assert f"com.amazonaws.us-east-1.{service}" in judged[0]["Finding_Details"]

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_s3express_is_a_different_service(self, mock_ac, mock_ec2):
        # The match is on the trailing service segment, so s3express does not
        # answer for s3.
        self._wire(
            mock_ac,
            mock_ec2,
            [
                self._agentcore_endpoint(),
                self._gateway_endpoint(
                    endpoint_id="vpce-s3express", service="s3express"
                ),
            ],
        )

        findings = agentcore_app.check_agentcore_vpc_endpoints()

        assert not self._naming(findings, "vpce-s3express")

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_data_path_endpoints_alone_still_fail_the_presence_leg(
        self, mock_ac, mock_ec2
    ):
        # Widening the policy and inbound legs must not let an account with an
        # S3 endpoint and no AgentCore endpoint read as privately connected.
        self._wire(mock_ac, mock_ec2, [self._gateway_endpoint()])

        findings = agentcore_app.check_agentcore_vpc_endpoints()

        assert len(findings) == 1
        assert findings[0]["Finding"] == "AgentCore VPC Endpoints Missing"
        assert findings[0]["Status"] == "Failed"

    @patch("agentcore_app.ec2_client")
    @patch("agentcore_app.agentcore_client")
    def test_the_resolution_names_endpoint_services_that_exist(self, mock_ac, mock_ec2):
        # describe-vpc-endpoint-services publishes bedrock-agentcore,
        # bedrock-agentcore-control and bedrock-agentcore.gateway. There is no
        # bedrock-agentcore-runtime endpoint service to create.
        self._wire(mock_ac, mock_ec2, [])

        findings = agentcore_app.check_agentcore_vpc_endpoints()
        resolution = findings[0]["Resolution"]

        assert "com.amazonaws.region.bedrock-agentcore.gateway" in resolution
        assert "bedrock-agentcore-runtime" not in resolution

    @pytest.mark.parametrize(
        ("service_name", "expected"),
        [
            ("com.amazonaws.us-east-1.s3", True),
            ("com.amazonaws.us-east-1.dynamodb", True),
            ("com.amazonaws.us-east-1.sagemaker.api", True),
            ("com.amazonaws.us-east-1.sagemaker.runtime", True),
            ("com.amazonaws.us-east-1.s3express", False),
            ("com.amazonaws.us-east-1.sagemaker.featurestore-runtime", False),
            ("com.amazonaws.us-east-1.bedrock-agentcore", False),
            ("", False),
            (None, False),
        ],
    )
    def test_the_data_path_match_covers_the_family(self, service_name, expected):
        assert agentcore_app._is_agentcore_data_path_endpoint(service_name) is expected

    @pytest.mark.parametrize(
        "service_name",
        [
            "com.amazonaws.us-east-1.bedrock-agentcore",
            "com.amazonaws.us-east-1.bedrock-agentcore-control",
            "com.amazonaws.us-east-1.bedrock-agentcore.gateway",
        ],
    )
    def test_every_agentcore_endpoint_service_still_matches(self, service_name):
        assert agentcore_app._is_agentcore_service_endpoint(service_name)


class TestExecutionRoleAndDnsCheckRegistration:
    """AC-48, AC-49 and AG-39 are registered like the checks they sit beside."""

    _CHECKS = {
        "AC-48": "check_agentcore_execution_role_trust_and_sharing",
        "AC-49": "check_agentcore_dns_egress_control",
    }

    @pytest.mark.parametrize("check_id", sorted(_CHECKS))
    def test_the_checks_are_in_both_regional_tuples(self, check_id):
        assert check_id in agentcore_app.REGIONAL_AGENTCORE_CHECK_IDS
        assert check_id in agentcore_app.AGENTCORE_RUNTIME_CHECK_IDS

    @pytest.mark.parametrize("check_id", sorted(_CHECKS) + ["AG-39"])
    def test_timeout_backfill_emits_the_checks(self, check_id):
        findings = agentcore_app.build_agentcore_timeout_findings("us-east-1", [])
        assert check_id in {finding["Check_ID"] for finding in findings}

    @pytest.mark.parametrize("check_id", sorted(_CHECKS) + ["AG-39"])
    def test_the_runtime_probe_backfill_emits_the_checks(self, check_id):
        findings = []
        agentcore_app.prepare_agentcore_runtime_incomplete_report_findings(
            findings, "us-east-1", "ExpiredToken"
        )
        assert check_id in {finding["Check_ID"] for finding in findings}

    @pytest.mark.parametrize("function_name", sorted(_CHECKS.values()))
    def test_the_handler_registers_each_check_once(self, function_name):
        source = textwrap.dedent(inspect.getsource(agentcore_app.lambda_handler))
        assert source.count(function_name) == 1

    def test_ag39_is_a_native_gateway_control(self):
        assert (
            agentcore_app.NATIVE_AGENTIC_AGENTCORE_CHECK_NAMES["AG-39"]
            == "Agentic AI Gateway WAF Rule Coverage"
        )

    @pytest.mark.parametrize("client_name", ["wafv2_client", "route53resolver_client"])
    def test_the_handler_creates_the_new_clients_for_the_target_region(
        self, client_name
    ):
        # A gateway's web ACL is a REGIONAL ACL in the gateway's own region and a
        # DNS Firewall association lives in the VPC's region, so neither client
        # may be built without region_name.
        source = textwrap.dedent(inspect.getsource(agentcore_app.lambda_handler))
        assignment = source.split(f"{client_name} = ", 1)[1].split(")", 1)[0]
        assert "region_name=region" in assignment
        assert "global wafv2_client, route53resolver_client" in source


class TestAC26LogDeletionProtection:
    """AC-26: deletion protection on runtime log groups and on aws/spans."""

    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.logs_client")
    def test_runtime_groups_are_judged_one_by_one(self, mock_logs, mock_kms):
        mock_logs.describe_log_groups.side_effect = _log_group_side_effect(
            {
                "/aws/bedrock-agentcore/": [
                    {
                        "logGroupName": "/aws/bedrock-agentcore/runtimes/rt-1",
                        "kmsKeyId": TestAC26LogRetentionAndKeyScope._KEY,
                        "retentionInDays": 30,
                        "deletionProtectionEnabled": True,
                    },
                    {
                        "logGroupName": "/aws/bedrock-agentcore/runtimes/rt-2",
                        "kmsKeyId": TestAC26LogRetentionAndKeyScope._KEY,
                        "retentionInDays": 30,
                        "deletionProtectionEnabled": False,
                    },
                ]
            }
        )

        mock_kms.get_key_policy.return_value = {
            "Policy": TestAC26LogRetentionAndKeyScope._SCOPED_KEY_POLICY
        }

        findings = agentcore_app.check_agentcore_log_retention_and_key_scope()

        assert [finding["Status"] for finding in findings] == ["Passed", "Failed"]
        assert "deletion protection enabled" in findings[0]["Finding_Details"]
        assert "rt-2" in findings[1]["Finding_Details"]
        assert "deletion protection off" in findings[1]["Finding_Details"]
        assert "deletion protection" in findings[1]["Resolution"]
        for finding in findings:
            assert_finding_schema(finding)

    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.logs_client")
    def test_an_absent_deletion_protection_field_reads_as_off(
        self, mock_logs, mock_kms
    ):
        mock_logs.describe_log_groups.side_effect = _log_group_side_effect(
            {
                "/aws/bedrock-agentcore/": [
                    {
                        "logGroupName": "/aws/bedrock-agentcore/runtimes/rt-1",
                        "retentionInDays": 30,
                    }
                ]
            }
        )

        findings = agentcore_app.check_agentcore_log_retention_and_key_scope()

        assert [finding["Status"] for finding in findings] == ["Failed"]
        assert "deletion protection off" in findings[0]["Finding_Details"]

    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.logs_client")
    def test_a_non_runtime_group_is_not_judged_for_deletion_protection(
        self, mock_logs, mock_kms
    ):
        # Round 2 holds the vended-log groups to deletion protection, so this
        # case now reads a group outside both the runtime and vended-log prefixes.
        mock_logs.describe_log_groups.side_effect = _log_group_side_effect(
            {
                "/aws/bedrock-agentcore/": [
                    {
                        "logGroupName": "/aws/bedrock-agentcore/evaluations/e1",
                        "kmsKeyId": TestAC26LogRetentionAndKeyScope._KEY,
                        "retentionInDays": 30,
                    }
                ]
            }
        )

        mock_kms.get_key_policy.return_value = {
            "Policy": TestAC26LogRetentionAndKeyScope._SCOPED_KEY_POLICY
        }

        findings = agentcore_app.check_agentcore_log_retention_and_key_scope()

        assert [finding["Status"] for finding in findings] == ["Passed"]
        assert "deletion protection" not in findings[0]["Finding_Details"]

    @pytest.mark.parametrize(
        "span_group, status",
        [
            (
                {"logGroupName": "aws/spans", "deletionProtectionEnabled": True},
                "Passed",
            ),
            (
                {"logGroupName": "aws/spans", "deletionProtectionEnabled": False},
                "Failed",
            ),
            ({"logGroupName": "aws/spans", "retentionInDays": 30}, "Failed"),
        ],
    )
    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.logs_client")
    def test_the_spans_group_gets_its_own_row(
        self, mock_logs, mock_kms, span_group, status
    ):
        mock_logs.describe_log_groups.side_effect = _log_group_side_effect(
            {
                "/aws/bedrock-agentcore/": [
                    {
                        "logGroupName": "/aws/bedrock-agentcore/runtimes/rt-1",
                        "retentionInDays": 30,
                        "deletionProtectionEnabled": True,
                    }
                ],
                "aws/spans": [span_group],
            }
        )

        findings = agentcore_app.check_agentcore_log_retention_and_key_scope()

        spans = [
            finding
            for finding in findings
            if finding["Finding"] == "AgentCore Span Log Deletion Protection"
        ]
        assert [finding["Status"] for finding in spans] == [status]
        assert spans[0]["Check_ID"] == "AC-26"
        assert "aws/spans" in spans[0]["Finding_Details"]
        assert_finding_schema(spans[0])
        assert {"logGroupNamePrefix": "aws/spans"} in [
            call.kwargs for call in mock_logs.describe_log_groups.call_args_list
        ]

    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.logs_client")
    def test_a_prefix_lookalike_is_not_the_spans_group(self, mock_logs, mock_kms):
        mock_logs.describe_log_groups.side_effect = _log_group_side_effect(
            {
                "/aws/bedrock-agentcore/": [
                    {
                        "logGroupName": "/aws/bedrock-agentcore/runtimes/rt-1",
                        "retentionInDays": 30,
                        "deletionProtectionEnabled": True,
                    }
                ],
                "aws/spans": [{"logGroupName": "aws/spans-archive"}],
            }
        )

        findings = agentcore_app.check_agentcore_log_retention_and_key_scope()

        assert [finding["Finding"] for finding in findings] == [
            "AgentCore Log Retention and Key Scope"
        ]

    @patch("agentcore_app.kms_client")
    @patch("agentcore_app.logs_client")
    def test_an_unreadable_spans_group_is_incomplete_beside_the_runtime_rows(
        self, mock_logs, mock_kms
    ):
        runtime_groups = _log_group_side_effect(
            {
                "/aws/bedrock-agentcore/": [
                    {
                        "logGroupName": "/aws/bedrock-agentcore/runtimes/rt-1",
                        "kmsKeyId": TestAC26LogRetentionAndKeyScope._KEY,
                        "retentionInDays": 30,
                        "deletionProtectionEnabled": True,
                    }
                ]
            }
        )

        def describe(**kwargs):
            if kwargs.get("logGroupNamePrefix") == "aws/spans":
                raise _make_client_error("AccessDeniedException", "no")
            return runtime_groups(**kwargs)

        mock_logs.describe_log_groups.side_effect = describe

        mock_kms.get_key_policy.return_value = {
            "Policy": TestAC26LogRetentionAndKeyScope._SCOPED_KEY_POLICY
        }

        findings = agentcore_app.check_agentcore_log_retention_and_key_scope()

        assert [finding["Status"] for finding in findings] == ["Passed", "N/A"]
        assert findings[1]["Finding"] == (
            "AgentCore Span Log Deletion Protection Incomplete"
        )


def _ecr_repo(name):
    return {"repositoryName": name}


def _scanning(scan_type, *rules):
    return {
        "scanningConfiguration": {
            "scanType": scan_type,
            "rules": [
                {
                    "scanFrequency": frequency,
                    "repositoryFilters": [
                        {"filter": pattern, "filterType": "WILDCARD"}
                        for pattern in patterns
                    ],
                }
                for frequency, patterns in rules
            ],
        }
    }


class TestAC50EcrEnhancedScanning:
    """AC-50: enhanced scanning covers every AgentCore image repository."""

    @patch("agentcore_app.ecr_client", None)
    def test_no_client_is_na(self):
        findings = agentcore_app.check_agentcore_ecr_enhanced_scanning()
        assert [finding["Status"] for finding in findings] == ["N/A"]
        assert findings[0]["Check_ID"] == "AC-50"
        assert_finding_schema(findings[0])

    @patch("agentcore_app.ecr_client")
    def test_no_agentcore_repository_is_na(self, mock_ecr):
        mock_ecr.describe_repositories.return_value = {
            "repositories": [_ecr_repo("web-frontend")]
        }

        findings = agentcore_app.check_agentcore_ecr_enhanced_scanning()

        assert [finding["Status"] for finding in findings] == ["N/A"]
        mock_ecr.get_registry_scanning_configuration.assert_not_called()

    @patch("agentcore_app.ecr_client")
    def test_basic_scanning_fails_every_repository(self, mock_ecr):
        mock_ecr.describe_repositories.return_value = {
            "repositories": [_ecr_repo("agentcore-a"), _ecr_repo("bedrock-agent-b")]
        }
        mock_ecr.get_registry_scanning_configuration.return_value = _scanning(
            "BASIC", ("SCAN_ON_PUSH", ["*"])
        )

        findings = agentcore_app.check_agentcore_ecr_enhanced_scanning()

        assert [finding["Status"] for finding in findings] == ["Failed", "Failed"]
        assert "agentcore-a" in findings[0]["Finding_Details"]
        assert "bedrock-agent-b" in findings[1]["Finding_Details"]
        for finding in findings:
            assert "BASIC" in finding["Finding_Details"]
            assert_finding_schema(finding)

    @patch("agentcore_app.ecr_client")
    def test_a_wildcard_filter_that_misses_a_repository_fails_that_repository(
        self, mock_ecr
    ):
        mock_ecr.describe_repositories.return_value = {
            "repositories": [
                _ecr_repo("agentcore-a"),
                _ecr_repo("team/bedrock-agent-b"),
            ]
        }
        mock_ecr.get_registry_scanning_configuration.return_value = _scanning(
            "ENHANCED", ("CONTINUOUS_SCAN", ["agentcore-*"])
        )

        findings = agentcore_app.check_agentcore_ecr_enhanced_scanning()

        assert [finding["Status"] for finding in findings] == ["Passed", "Failed"]
        assert "CONTINUOUS_SCAN" in findings[0]["Finding_Details"]
        assert "team/bedrock-agent-b" in findings[1]["Finding_Details"]
        assert "Off" in findings[1]["Finding_Details"]

    @patch("agentcore_app.ecr_client")
    def test_continuous_scanning_wins_over_scan_on_push(self, mock_ecr):
        mock_ecr.describe_repositories.return_value = {
            "repositories": [_ecr_repo("agentcore-a"), _ecr_repo("agentcore-b")]
        }
        mock_ecr.get_registry_scanning_configuration.return_value = _scanning(
            "ENHANCED",
            ("SCAN_ON_PUSH", ["*"]),
            ("CONTINUOUS_SCAN", ["agentcore-a"]),
        )

        findings = agentcore_app.check_agentcore_ecr_enhanced_scanning()

        assert [finding["Status"] for finding in findings] == ["Passed", "Failed"]
        assert "CONTINUOUS_SCAN" in findings[0]["Finding_Details"]
        assert "SCAN_ON_PUSH" in findings[1]["Finding_Details"]

    @patch("agentcore_app.ecr_client")
    def test_a_manual_frequency_rule_is_not_coverage(self, mock_ecr):
        mock_ecr.describe_repositories.return_value = {
            "repositories": [_ecr_repo("agentcore-a")]
        }
        mock_ecr.get_registry_scanning_configuration.return_value = _scanning(
            "ENHANCED", ("MANUAL", ["*"])
        )

        findings = agentcore_app.check_agentcore_ecr_enhanced_scanning()

        assert [finding["Status"] for finding in findings] == ["Failed"]

    @patch("agentcore_app.ecr_client")
    def test_an_absent_scan_type_fails(self, mock_ecr):
        mock_ecr.describe_repositories.return_value = {
            "repositories": [_ecr_repo("agentcore-a")]
        }
        mock_ecr.get_registry_scanning_configuration.return_value = {}

        findings = agentcore_app.check_agentcore_ecr_enhanced_scanning()

        assert [finding["Status"] for finding in findings] == ["Failed"]
        assert "not set" in findings[0]["Finding_Details"]

    @patch("agentcore_app.ecr_client")
    def test_repositories_on_a_later_page_are_judged(self, mock_ecr):
        mock_ecr.describe_repositories.side_effect = [
            {"repositories": [_ecr_repo("agentcore-a")], "nextToken": "t1"},
            {"repositories": [_ecr_repo("other"), _ecr_repo("agentcore-b")]},
        ]
        mock_ecr.get_registry_scanning_configuration.return_value = _scanning(
            "ENHANCED", ("CONTINUOUS_SCAN", ["agentcore-a"])
        )

        findings = agentcore_app.check_agentcore_ecr_enhanced_scanning()

        assert [finding["Status"] for finding in findings] == ["Passed", "Failed"]
        assert "agentcore-b" in findings[1]["Finding_Details"]
        assert mock_ecr.describe_repositories.call_args_list[1].kwargs == {
            "nextToken": "t1"
        }

    @patch("agentcore_app.ecr_client")
    def test_an_unreadable_scanning_configuration_is_incomplete(self, mock_ecr):
        mock_ecr.describe_repositories.return_value = {
            "repositories": [_ecr_repo("agentcore-a")]
        }
        mock_ecr.get_registry_scanning_configuration.side_effect = _make_client_error(
            "AccessDeniedException", "no"
        )

        findings = agentcore_app.check_agentcore_ecr_enhanced_scanning()

        assert [finding["Status"] for finding in findings] == ["N/A"]
        assert findings[0]["Finding"] == "AgentCore ECR Enhanced Scanning Incomplete"

    # The ECR user guide's filter table ("Filters to choose which repositories
    # are scanned"): filters down the side, repository names across the top.
    _ECR_GUIDE_NAMES = ("prod", "repo-prod", "prod-repo", "repo-prod-repo", "prodrepo")
    _ECR_GUIDE_TABLE = {
        "prod": (True, True, True, True, True),
        "*prod": (True, True, False, False, False),
        "prod*": (True, False, True, False, True),
    }

    @pytest.mark.parametrize("pattern", sorted(_ECR_GUIDE_TABLE))
    def test_filter_matching_follows_the_ecr_guide_table(self, pattern):
        assert (
            tuple(
                agentcore_app._ecr_scanning_filter_matches(pattern, name)
                for name in self._ECR_GUIDE_NAMES
            )
            == self._ECR_GUIDE_TABLE[pattern]
        )


def _image_uri(repo, account="123456789012", region="us-east-1", ref=":v1"):
    return f"{account}.dkr.ecr.{region}.amazonaws.com/{repo}{ref}"


def _runtimes_with_images(mock_ac, images):
    """Answer ListAgentRuntimes and GetAgentRuntime for runtime id to image.

    An image of None is a runtime deployed from code, and an exception is what
    GetAgentRuntime raises for that runtime.
    """
    mock_ac.list_agent_runtimes.return_value = {
        "agentRuntimes": [
            {"agentRuntimeId": runtime_id, "agentRuntimeName": f"name-{runtime_id}"}
            for runtime_id in images
        ]
    }

    def get_agent_runtime(agentRuntimeId):
        image = images[agentRuntimeId]
        if isinstance(image, Exception):
            raise image
        if image is None:
            artifact = {"codeConfiguration": {"entryPoint": ["main.py"]}}
        else:
            artifact = {"containerConfiguration": {"containerUri": image}}
        return {"agentRuntimeId": agentRuntimeId, "agentRuntimeArtifact": artifact}

    mock_ac.get_agent_runtime.side_effect = get_agent_runtime


def _owned_repo(name, registry_id="123456789012"):
    return {"repositoryName": name, "registryId": registry_id}


