    @staticmethod
    def _tools(system, custom):
        def lister(key):
            def call(**kwargs):
                ids = system if kwargs.get("type") == "SYSTEM" else custom
                return {key: [{"id": i} for i in ids]}

            return call

        return lister("codeInterpreterSummaries"), lister("browserSummaries")

